#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MessageFilter {
    All,
    Unread,
    Flagged,
    Important,
    HasAttachments,
}

impl MessageFilter {
    fn from_selector_index(index: u32) -> Self {
        match index {
            1 => Self::Unread,
            2 => Self::Flagged,
            3 => Self::Important,
            4 => Self::HasAttachments,
            _ => Self::All,
        }
    }

    fn selector_index(self) -> u32 {
        match self {
            Self::All => 0,
            Self::Unread => 1,
            Self::Flagged => 2,
            Self::Important => 3,
            Self::HasAttachments => 4,
        }
    }
}

