    fn load_mail_history_async(&self) {
        let generation = self.imp().mail_history_generation.get();
        let history_path = MailCommandStack::capture_persistent_path();
        let cancellation = Arc::new(AtomicBool::new(false));
        self.imp()
            .mail_history_load_cancellation
            .replace(Some(cancellation.clone()));

        let (sender, receiver) = async_channel::bounded(1);
        let worker_cancellation = cancellation.clone();
        std::thread::spawn(move || {
            let history = MailCommandStack::load_persistent_from_path(history_path);
            if !worker_cancellation.load(Ordering::Relaxed) {
                let _ = sender.send_blocking(history);
            }
        });

        let page = self.downgrade();
        glib::spawn_future_local(async move {
            let history = receiver.recv().await.ok();
            let Some(page) = page.upgrade() else {
                return;
            };
            let is_current = page
                .imp()
                .mail_history_load_cancellation
                .borrow()
                .as_ref()
                .is_some_and(|current| Arc::ptr_eq(current, &cancellation));
            if !is_current {
                return;
            }
            page.imp()
                .mail_history_load_cancellation
                .borrow_mut()
                .take();

            if let Some(history) = history
                && !cancellation.load(Ordering::Relaxed)
                && page.imp().mail_history_generation.get() == generation
            {
                page.imp().mail_commands.replace(history);
                page.update_undelete_action();
            }
        });
    }

    fn persist_mail_history_async(&self) {
        let sequence = self
            .imp()
            .mail_history_persist_sequence
            .get()
            .saturating_add(1);
        self.imp().mail_history_persist_sequence.set(sequence);
        let snapshot = self.imp().mail_commands.borrow().clone();
        let persisted_sequence = Arc::clone(&self.imp().mail_history_persisted_sequence);
        std::thread::spawn(move || {
            let mut last_persisted = persisted_sequence
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if sequence <= *last_persisted {
                return;
            }
            snapshot.persist_snapshot();
            *last_persisted = sequence;
        });
    }

    pub fn undo(&self) -> Result<bool, MailOperationError> {
        let Some(operation) = self.imp().mail_commands.borrow().undo_operation_kind() else {
            return Ok(false);
        };
        self.execute_history_action(true, operation)?;
        Ok(true)
    }

    /// Recover only the current delete history entry.  Calling the generic
    /// undo action here would allow this reader action to roll back an
    /// unrelated read, flag, move, or archive operation.
    pub fn undelete(&self) -> Result<bool, MailOperationError> {
        if !self.can_undelete() {
            return Ok(false);
        }
        let selected = self.selected_local_deleted_messages();
        if !selected.is_empty() {
            let commands = selected
                .iter()
                .map(|message| MailCommand::restore_deleted_local(message.id()))
                .collect::<Vec<_>>();
            if commands.len() == 1 {
                self.execute_mail_command(
                    commands
                        .into_iter()
                        .next()
                        .expect("one selected restore command"),
                )?;
            } else {
                self.execute_mail_batch(commands, &crate::i18n::gettext("Restore messages"))?;
            }
            return Ok(true);
        }
        // A normal primary row is often auto-selected after a delete refresh,
        // so retain the Delete-head recovery in that common case.  An explicit
        // batch, however, is a user-directed multi-selection and must never
        // fall through to unrelated history.
        if !self.imp().batch_selection.borrow().is_empty() {
            return Ok(false);
        }
        self.execute_history_action(true, MailOperationKind::Delete)?;
        self.update_undelete_action();
        Ok(true)
    }

    pub fn redo(&self) -> Result<bool, MailOperationError> {
        let Some(operation) = self.imp().mail_commands.borrow().redo_operation_kind() else {
            return Ok(false);
        };
        self.execute_history_action(false, operation)?;
        Ok(true)
    }

    pub fn mark_message_unread(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        message.set_unread(true);

        let command = MailCommand::set_message_state(
            message.id(),
            message.backend_location(),
            false,
            message.is_flagged(),
            true,
            message.is_flagged(),
        );
        self.execute_mail_command(command)?;
        self.refresh_unread_counters();
        self.queue_mail_table_draw();
        Ok(true)
    }

    pub fn mark_selected_unread(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_marked = false;
        for message in messages {
            if self.mark_message_unread(&message)? {
                any_marked = true;
            }
        }
        Ok(any_marked)
    }

    pub fn mark_message_read(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        message.set_unread(false);

        let command = MailCommand::set_message_state(
            message.id(),
            message.backend_location(),
            true,
            message.is_flagged(),
            false,
            message.is_flagged(),
        );
        self.execute_mail_command(command)?;
        self.refresh_unread_counters();
        self.queue_mail_table_draw();
        Ok(true)
    }

    pub fn mark_selected_read(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_marked = false;
        for message in messages {
            if self.mark_message_read(&message)? {
                any_marked = true;
            }
        }
        Ok(any_marked)
    }

    pub fn toggle_selected_flagged(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        if messages.iter().any(|message| {
            message
                .backend_location()
                .as_ref()
                .is_some_and(|location| is_graph_backend_location(Some(location)))
        }) {
            return Err(MailOperationError::Unsupported {
                operation:
                    crate::services::mail_operations_service::MailOperationKind::SetMessageState,
                backend: "Graph (please use separate follow-up flag)",
            });
        }
        let next_flagged = messages.iter().any(|message| !message.is_flagged());
        for message in &messages {
            message.set_flagged(next_flagged);
            let command = MailCommand::set_message_state(
                message.id(),
                message.backend_location(),
                message.is_unread(),
                !next_flagged,
                message.is_unread(),
                next_flagged,
            );
            self.execute_mail_command(command)?;
        }
        self.queue_mail_table_draw();
        Ok(true)
    }

    pub(crate) fn queue_mail_table_draw(&self) {
        self.imp().mail_table_layout.replace(None);
        if let Some(canvas) = self.imp().mail_table_canvas.borrow().as_ref() {
            canvas.queue_draw();
        }
        if let Some(view) = self.imp().mail_list_view.borrow().as_ref() {
            view.queue_draw();
        }
    }

    pub fn toggle_message_flagged(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        let next_flagged = !message.is_flagged();
        message.set_flagged(next_flagged);
        let command = MailCommand::set_message_state(
            message.id(),
            message.backend_location(),
            message.is_unread(),
            !next_flagged,
            message.is_unread(),
            next_flagged,
        );
        let res = self.execute_mail_command(command);
        self.queue_mail_table_draw();
        res.map(|_| true)
    }

    pub fn toggle_message_unread(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        let res = if message.is_unread() {
            self.mark_message_read(message)
        } else {
            self.mark_message_unread(message)
        };
        self.queue_mail_table_draw();
        res
    }

    fn set_message_follow_up(
        &self,
        message: &MailMessageObject,
        metadata: MailFollowUpMetadata,
    ) -> Result<(), MailOperationError> {
        let command = MailCommand::set_follow_up(
            message.id(),
            message.backend_location(),
            message.follow_up(),
            metadata,
        );
        self.execute_mail_command(command)
    }

    pub fn cycle_message_follow_up(
        &self,
        message: &MailMessageObject,
    ) -> Result<MailFollowUpState, MailOperationError> {
        let current_state = message.follow_up_state();
        let next_metadata = match current_state {
            MailFollowUpState::None => {
                MailFollowUpMetadata::pending(Some(DEFAULT_FOLLOW_UP_TEXT.to_string()), None)
            }
            MailFollowUpState::FollowUp => {
                MailFollowUpMetadata::completed_from(
                    &message.follow_up(),
                    chrono::Utc::now().to_rfc2822(),
                )
            }
            MailFollowUpState::Completed => {
                MailFollowUpMetadata::none()
            }
        };
        let next_state = next_metadata.state;
        message.set_follow_up(next_metadata.clone());
        let res = self.set_message_follow_up(message, next_metadata);
        self.queue_mail_table_draw();
        res.map(|_| next_state)
    }


    /// Present Evolution's explicit follow-up editor for the selected
    /// message. The ordinary star remains a separate action and column.
    pub fn edit_selected_follow_up(&self) -> bool {
        let Some(message) = self.selected_message() else {
            return false;
        };
        self.present_follow_up_editor(&message);
        true
    }

    fn present_follow_up_editor(&self, message: &MailMessageObject) {
        let title = gettext("Follow-up");
        let dialog = adw::Window::builder()
            .title(&title)
            .modal(true)
            .default_width(420)
            .build();
        if let Some(root) = self.root().and_downcast::<gtk::Window>() {
            dialog.set_transient_for(Some(&root));
        }

        let toolbar = adw::ToolbarView::new();
        let header = adw::HeaderBar::new();
        let cancel = gtk::Button::with_label(&gettext("Cancel"));
        let save = gtk::Button::builder()
            .label(&gettext("Save"))
            .css_classes(vec!["suggested-action"])
            .build();
        header.pack_start(&cancel);
        header.pack_end(&save);
        toolbar.add_top_bar(&header);

        let content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(12)
            .margin_start(20)
            .margin_end(20)
            .margin_top(16)
            .margin_bottom(20)
            .build();
        let group = adw::PreferencesGroup::builder()
            .title(&gettext("Follow-up"))
            .build();
        let text = adw::EntryRow::builder().title(&gettext("Flag")).build();
        let due = adw::EntryRow::builder()
            .title(&gettext("Due (YYYY-MM-DD HH:MM, optional)"))
            .build();
        let current = message.follow_up();
        text.set_text(current.text.as_deref().unwrap_or(DEFAULT_FOLLOW_UP_TEXT));
        due.set_text(&display_follow_up_due(current.due_by.as_deref()));
        group.add(&text);
        group.add(&due);
        content.append(&group);

        let is_graph = message
            .backend_location()
            .as_ref()
            .is_some_and(|location| is_graph_backend_location(Some(location)));
        if is_graph {
            due.set_sensitive(false);
            let warning = gtk::Label::builder()
                .label(&gettext("Microsoft Graph does not support follow-up due dates."))
                .wrap(true)
                .halign(gtk::Align::Start)
                .css_classes(vec!["warning", "dim-label"])
                .build();
            content.append(&warning);
        }

        let actions = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(6)
            .halign(gtk::Align::End)
            .build();
        let clear = gtk::Button::with_label(&gettext("Clear"));
        let complete = gtk::Button::with_label(&gettext("Mark as Completed"));
        complete.set_sensitive(current.state != MailFollowUpState::None);
        actions.append(&clear);
        actions.append(&complete);
        content.append(&actions);
        toolbar.set_content(Some(&content));
        dialog.set_content(Some(&toolbar));

        let dialog_for_cancel = dialog.clone();
        cancel.connect_clicked(move |_| dialog_for_cancel.close());
        let page = self.downgrade();
        let message_for_save = message.clone();
        let dialog_for_save = dialog.clone();
        save.connect_clicked(move |_| {
            let due_by = match parse_follow_up_due_input(&due.text()) {
                Ok(due_by) => due_by,
                Err(error) => {
                    if let Some(page) = page.upgrade() {
                        page.show_toast(&error);
                    }
                    return;
                }
            };
            let metadata = MailFollowUpMetadata::pending(Some(text.text().to_string()), due_by);
            if let Some(page) = page.upgrade() {
                match page.set_message_follow_up(&message_for_save, metadata) {
                    Ok(()) => dialog_for_save.close(),
                    Err(error) => {
                        page.show_toast(&gettext("Follow-up not possible: {error}").replace("{error}", &error.to_string()))
                    }
                }
            }
        });
        let page = self.downgrade();
        let message_for_clear = message.clone();
        let dialog_for_clear = dialog.clone();
        clear.connect_clicked(move |_| {
            if let Some(page) = page.upgrade() {
                match page.set_message_follow_up(&message_for_clear, MailFollowUpMetadata::none()) {
                    Ok(()) => dialog_for_clear.close(),
                    Err(error) => {
                        page.show_toast(&gettext("Follow-up not possible: {error}").replace("{error}", &error.to_string()))
                    }
                }
            }
        });
        let page = self.downgrade();
        let message_for_complete = message.clone();
        let dialog_for_complete = dialog.clone();
        complete.connect_clicked(move |_| {
            let metadata = MailFollowUpMetadata::completed_from(
                &message_for_complete.follow_up(),
                Utc::now().to_rfc2822(),
            );
            if let Some(page) = page.upgrade() {
                match page.set_message_follow_up(&message_for_complete, metadata) {
                    Ok(()) => dialog_for_complete.close(),
                    Err(error) => {
                        page.show_toast(&gettext("Follow-up not possible: {error}").replace("{error}", &error.to_string()))
                    }
                }
            }
        });
        dialog.present();
    }

    pub fn toggle_selected_important(&self) -> Result<bool, MailOperationError> {
        let Some(message) = self.selected_message() else {
            return Ok(false);
        };
        if message
            .backend_location()
            .as_ref()
            .is_some_and(|location| !is_graph_backend_location(Some(location)))
        {
            return Err(MailOperationError::Unsupported {
                operation: if message.is_important() {
                    crate::services::mail_operations_service::MailOperationKind::MarkNotImportant
                } else {
                    crate::services::mail_operations_service::MailOperationKind::MarkImportant
                },
                backend: "importance flag for this account (pending Linux signoff)",
            });
        }
        let next_important = !message.is_important();
        let command = message
            .backend_location()
            .map(|location| {
                MailCommand::set_important(
                    message.id(),
                    location,
                    message.is_important(),
                    next_important,
                )
            })
            .unwrap_or_else(|| {
                MailCommand::set_important_local(
                    message.id(),
                    message.is_important(),
                    next_important,
                )
            });
        self.execute_mail_command(command)?;
        Ok(true)
    }

    fn set_selected_label(&self, label: &str, labeled: bool) -> Result<bool, MailOperationError> {
        let label = label.trim();
        if label.is_empty() {
            return Ok(false);
        }
        let Some(message) = self.selected_message() else {
            return Ok(false);
        };
        if message
            .backend_location()
            .as_ref()
            .is_some_and(|location| !is_graph_backend_location(Some(location)))
        {
            return Err(MailOperationError::Unsupported {
                operation: crate::services::mail_operations_service::MailOperationKind::SetLabel,
                backend: "multiple labels for this account",
            });
        }

        let before = message.has_label(label);
        if before == labeled {
            return Ok(true);
        }
        let command = message
            .backend_location()
            .map(|location| {
                MailCommand::set_label_for_location(message.id(), location, label, before, labeled)
            })
            .unwrap_or_else(|| MailCommand::set_label_local(message.id(), label, before, labeled));
        self.execute_mail_command(command)?;
        Ok(true)
    }

    fn set_batch_label(&self, label: &str, labeled: bool) -> Result<usize, MailOperationError> {
        let label = label.trim();
        if label.is_empty() {
            return Ok(0);
        }
        let messages = self.selected_batch_messages();
        if messages.is_empty() {
            return Ok(0);
        }
        if messages.iter().any(|message| {
            message
                .backend_location()
                .as_ref()
                .is_some_and(|location| !is_graph_backend_location(Some(location)))
        }) {
            return Err(MailOperationError::Unsupported {
                operation: crate::services::mail_operations_service::MailOperationKind::SetLabel,
                backend: "multiple labels for this account",
            });
        }

        let commands = messages
            .iter()
            .filter_map(|message| {
                let before = message.has_label(label);
                (before != labeled).then(|| {
                    message
                        .backend_location()
                        .map(|location| {
                            MailCommand::set_label_for_location(
                                message.id(),
                                location,
                                label,
                                before,
                                labeled,
                            )
                        })
                        .unwrap_or_else(|| {
                            MailCommand::set_label_local(message.id(), label, before, labeled)
                        })
                })
            })
            .collect::<Vec<_>>();
        let count = commands.len();
        if count > 0 {
            self.execute_mail_batch(commands, &gettext("Change labels"))?;
        }
        Ok(count)
    }

    pub(crate) fn present_label_editor(&self) {
        let has_batch = !self.imp().batch_selection.borrow().is_empty();
        if !has_batch && self.selected_message().is_none() {
            self.show_toast(&gettext("No message selected"));
            return;
        }
        let Some(parent) = self.root().and_downcast::<gtk::Window>() else {
            tracing::warn!("Cannot open label editor without a parent window");
            return;
        };

        let configured_labels = AppSettings::try_new()
            .map(|s| s.mail_labels())
            .unwrap_or_else(crate::services::settings_service::MailLabelDefinition::default_labels);

        let current_labels = if has_batch {
            Vec::new()
        } else {
            self.selected_message()
                .map(|m| m.labels())
                .unwrap_or_default()
        };

        let dialog_title = if has_batch {
            gettext("Labels for Selection")
        } else {
            gettext("Message Labels")
        };
        let dialog = adw::Window::builder()
            .title(&dialog_title)
            .modal(true)
            .default_width(440)
            .default_height(380)
            .build();
        dialog.set_transient_for(Some(&parent));

        let toolbar = adw::ToolbarView::new();
        let header = adw::HeaderBar::new();
        let close_button = gtk::Button::builder()
            .label(&gettext("Close"))
            .css_classes(vec!["suggested-action"])
            .build();
        header.pack_end(&close_button);
        toolbar.add_top_bar(&header);

        let content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(12)
            .margin_start(16)
            .margin_end(16)
            .margin_top(16)
            .margin_bottom(16)
            .build();

        let group_labels = adw::PreferencesGroup::builder()
            .title(&gettext("Standard and Custom Labels"))
            .build();

        for label_def in configured_labels {
            let tag = label_def.tag.clone();
            let name = label_def.name.clone();
            let display_name = label_def.display_name();
            let color = label_def.color.clone();

            let is_active = current_labels
                .iter()
                .any(|l| l.eq_ignore_ascii_case(&tag) || l.eq_ignore_ascii_case(&name));

            let row = adw::SwitchRow::builder()
                .title(&display_name)
                .subtitle(format!("Tag: {tag} · {color}"))
                .active(is_active)
                .build();

            let color_dot = gtk::Label::builder()
                .label("●")
                .css_classes(vec!["title-2"])
                .valign(gtk::Align::Center)
                .margin_end(8)
                .build();
            color_dot.set_markup(&format!(
                "<span foreground=\"{color}\" font_size=\"x-large\">●</span>"
            ));
            row.add_prefix(&color_dot);

            let page_weak = self.downgrade();
            let tag_for_toggle = tag.clone();
            row.connect_active_notify(move |switch_row| {
                let Some(page) = page_weak.upgrade() else {
                    return;
                };
                let active = switch_row.is_active();
                let result = if has_batch {
                    page.set_batch_label(&tag_for_toggle, active)
                        .map(|count| {
                            ngettext(
                                "{count} message updated",
                                "{count} messages updated",
                                count as u32,
                            ).replace("{count}", &count.to_string())
                        })
                } else {
                    page.set_selected_label(&tag_for_toggle, active).map(|_| {
                        if active {
                            gettext("Label added")
                        } else {
                            gettext("Label removed")
                        }
                    })
                };
                match result {
                    Ok(msg) => page.show_toast(&msg),
                    Err(error) => {
                        page.show_toast(&gettext("Label could not be updated: {error}").replace("{error}", &error.to_string()))
                    }
                }
            });

            group_labels.add(&row);
        }

        let group_custom = adw::PreferencesGroup::builder()
            .title(&gettext("Custom Label"))
            .description(&gettext("Specify custom tag or label name"))
            .build();

        let label_entry = adw::EntryRow::builder()
            .title(&gettext("Custom label"))
            .show_apply_button(false)
            .build();
        group_custom.add(&label_entry);

        let custom_actions = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(8)
            .margin_top(4)
            .build();

        let set_custom_btn = gtk::Button::builder()
            .label(&gettext("Set Label"))
            .css_classes(vec!["suggested-action", "flat"])
            .build();
        let remove_custom_btn = gtk::Button::builder()
            .label(&gettext("Remove Label"))
            .css_classes(vec!["destructive-action", "flat"])
            .build();

        custom_actions.append(&set_custom_btn);
        custom_actions.append(&remove_custom_btn);
        group_custom.add(&custom_actions);

        let page_for_set = self.downgrade();
        let entry_for_set = label_entry.clone();
        set_custom_btn.connect_clicked(move |_| {
            let label = entry_for_set.text().trim().to_string();
            let Some(page) = page_for_set.upgrade() else {
                return;
            };
            if label.is_empty() {
                page.show_toast(&gettext("Please enter a label name"));
                return;
            }
            let result = if has_batch {
                page.set_batch_label(&label, true)
                    .map(|count| {
                        ngettext(
                            "{count} message labeled",
                            "{count} messages labeled",
                            count as u32,
                        ).replace("{count}", &count.to_string())
                    })
            } else {
                page.set_selected_label(&label, true)
                    .map(|_| gettext("Label set"))
            };
            match result {
                Ok(message) => page.show_toast(&message),
                Err(error) => {
                    page.show_toast(&gettext("Label could not be set: {error}").replace("{error}", &error.to_string()))
                }
            }
        });

        let page_for_remove = self.downgrade();
        let entry_for_remove = label_entry.clone();
        remove_custom_btn.connect_clicked(move |_| {
            let label = entry_for_remove.text().trim().to_string();
            let Some(page) = page_for_remove.upgrade() else {
                return;
            };
            if label.is_empty() {
                page.show_toast(&gettext("Please enter a label name"));
                return;
            }
            let result = if has_batch {
                page.set_batch_label(&label, false)
                    .map(|count| {
                        ngettext(
                            "Label removed from {count} message",
                            "Label removed from {count} messages",
                            count as u32,
                        ).replace("{count}", &count.to_string())
                    })
            } else {
                page.set_selected_label(&label, false)
                    .map(|_| gettext("Label removed"))
            };
            match result {
                Ok(message) => page.show_toast(&message),
                Err(error) => {
                    page.show_toast(&gettext("Label could not be removed: {error}").replace("{error}", &error.to_string()))
                }
            }
        });

        content.append(&group_labels);
        content.append(&group_custom);

        let scrolled = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(gtk::PolicyType::Automatic)
            .child(&content)
            .build();
        toolbar.set_content(Some(&scrolled));
        dialog.set_content(Some(&toolbar));

        let dialog_weak = dialog.downgrade();
        close_button.connect_clicked(move |_| {
            if let Some(d) = dialog_weak.upgrade() {
                d.close();
            }
        });

        dialog.present();
    }

    pub(crate) fn present_folder_destination_dialog(&self, copy: bool) {
        let Some(message) = self.selected_message() else {
            self.show_toast(&gettext("No message selected"));
            return;
        };
        let destinations = if copy {
            self.copy_folder_destinations_for_messages(std::slice::from_ref(&message))
        } else {
            self.folder_destinations_for_messages(std::slice::from_ref(&message))
        };
        if destinations.is_empty() {
            self.show_toast(&gettext("No destination folders available"));
            return;
        }
        let Some(parent) = self.root().and_downcast::<gtk::Window>() else {
            tracing::warn!("Cannot open folder destination dialog without a parent window");
            return;
        };

        let title_str = if copy {
            gettext("Copy Message")
        } else {
            gettext("Move Message")
        };
        let dialog = adw::Window::builder()
            .title(&title_str)
            .modal(true)
            .default_width(420)
            .default_height(520)
            .build();
        dialog.set_transient_for(Some(&parent));
        let toolbar = adw::ToolbarView::new();
        toolbar.add_top_bar(&adw::HeaderBar::new());
        let list = gtk::ListBox::builder()
            .selection_mode(gtk::SelectionMode::None)
            .css_classes(vec!["boxed-list"])
            .build();
        for destination in destinations {
            let button = gtk::Button::builder()
                .label(&destination.label)
                .halign(gtk::Align::Fill)
                .hexpand(true)
                .css_classes(vec!["flat"])
                .build();
            let page = self.downgrade();
            let dialog_weak = dialog.downgrade();
            let source_uid = destination.source_uid;
            let folder_name = destination.folder_name;
            let title = title_str.clone();
            button.connect_clicked(move |_| {
                let Some(page) = page.upgrade() else {
                    return;
                };
                let result = if copy {
                    page.copy_selected_to(&source_uid, &folder_name)
                } else {
                    page.move_selected_to(&source_uid, &folder_name)
                };
                match result {
                    Ok(true) => {
                        page.show_toast(&if copy {
                            gettext("Copying message")
                        } else {
                            gettext("Moving message")
                        });
                        if let Some(dialog) = dialog_weak.upgrade() {
                            dialog.close();
                        }
                    }
                    Ok(false) => page.show_toast(&gettext("No message selected")),
                    Err(error) => page.show_toast(&gettext("{title} not possible: {error}").replace("{title}", &title).replace("{error}", &error.to_string())),
                }
            });
            list.append(&button);
        }
        let content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .margin_start(12)
            .margin_end(12)
            .margin_top(12)
            .margin_bottom(12)
            .build();
        content.append(&list);
        let scrolled = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(gtk::PolicyType::Automatic)
            .child(&content)
            .build();
        toolbar.set_content(Some(&scrolled));
        dialog.set_content(Some(&toolbar));
        dialog.present();
    }

    pub fn archive_selected(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        for message in messages {
            let command = message
                .backend_location()
                .map(|location| MailCommand::archive(message.id(), location))
                .unwrap_or_else(|| MailCommand::archive_local(message.id(), message.folder_id()));
            self.execute_mail_command(command)?;
        }
        Ok(true)
    }

    pub fn mark_message_junk(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        let command = message
            .backend_location()
            .map(|location| {
                MailCommand::set_junk(message.id(), location, message_is_junk(message), true)
            })
            .unwrap_or_else(|| MailCommand::set_junk_local(message.id(), message.folder_id()));
        self.execute_mail_command(command)?;
        Ok(true)
    }

    pub fn mark_selected_junk(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_marked = false;
        for message in messages {
            if self.mark_message_junk(&message)? {
                any_marked = true;
            }
        }
        Ok(any_marked)
    }

    pub fn mark_message_not_junk(&self, message: &MailMessageObject) -> Result<bool, MailOperationError> {
        if !message_is_junk(message) {
            return Ok(true);
        }
        let command = message
            .backend_location()
            .map(|location| MailCommand::set_junk(message.id(), location, true, false))
            .unwrap_or_else(|| MailCommand::clear_junk_local(message.id()));
        self.execute_mail_command(command)?;
        Ok(true)
    }

    pub fn mark_selected_not_junk(&self) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_marked = false;
        for message in messages {
            if self.mark_message_not_junk(&message)? {
                any_marked = true;
            }
        }
        Ok(any_marked)
    }

    pub fn apply_filters(&self) {
        let worker_scope = self.mail_worker_ui_scope();
        let store_config = mail_store_worker_config_from_main_thread();
        let filter_store = MailFilterStore::default();
        let (sender, receiver) = async_channel::bounded(1);
        std::thread::spawn(move || {
            let result = MailStoreService::new_worker_safe(store_config)
                .run_all_active_filters_with_store(&filter_store);
            if let Err(error) = sender.send_blocking(result) {
                tracing::debug!(%error, "Apply filters result channel dropped");
            }
        });

        let page_weak = self.downgrade();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page_weak.upgrade() else {
                return;
            };
            if !page.mail_worker_ui_scope_is_current(&worker_scope) {
                tracing::debug!("Ignoring stale apply-filters result for a replaced mail scope");
                return;
            }
            match result {
                Ok(Ok(report)) => {
                    page.refresh_mail();
                    if AppSettings::try_new().map(|s| s.flush_outbox()).unwrap_or(false) {
                        page.flush_outbox_if_needed();
                    }
                    if report.matched_messages == 0 {
                        page.show_toast(&gettext("No matching messages for active filter rules"));
                    } else {
                        page.show_toast(&gettext("Filters applied: {matched} matches · {moved} moved · {deleted} deleted")
                            .replace("{matched}", &report.matched_messages.to_string())
                            .replace("{moved}", &report.moved_messages.to_string())
                            .replace("{deleted}", &report.deleted_messages.to_string()));
                    }
                }
                Ok(Err(error)) => {
                    page.show_toast(&format!("{}: {error}", gettext("Filtering failed")));
                }
                Err(error) => {
                    page.show_toast(&format!("{}: {error}", gettext("Filtering cancelled")));
                }
            }
        });
    }

    /// Lookup a MailMessageObject in the loaded message store or thread hierarchy.
    pub(crate) fn find_message_by_id(&self, message_id: &str) -> Option<MailMessageObject> {
        if let Some(store) = self.imp().message_store.borrow().as_ref() {
            for index in 0..store.n_items() {
                if let Some(msg) = store.item(index).and_downcast::<MailMessageObject>() {
                    if msg.id() == message_id {
                        return Some(msg);
                    }
                }
            }
        }
        if let Some(members_map) = self.imp().thread_members.borrow().as_ref() {
            for members in members_map.borrow().values() {
                if let Some(msg) = members.iter().find(|m| m.id() == message_id) {
                    return Some(msg.clone());
                }
            }
        }
        None
    }

    /// Move a specific message object to the specified destination source and folder.
    pub(crate) fn move_message_to(
        &self,
        message: &MailMessageObject,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let command = if destination_source == "local" {
            if message.backend_location().is_some() {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Move,
                    backend: "message from account to local import",
                });
            }
            MailCommand::move_local(
                message.id(),
                message.folder_id(),
                destination_folder.to_string(),
            )
        } else {
            let Some(location) = message.backend_location() else {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Move,
                    backend: "local import to an account",
                });
            };
            if location.source_uid != destination_source {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Move,
                    backend: "different account",
                });
            }
            MailCommand::move_to(message.id(), location, destination_folder.to_string())
        };

        self.execute_mail_command(command)?;
        Ok(true)
    }

    /// Copy a specific message object to the specified destination source and folder.
    pub(crate) fn copy_message_to(
        &self,
        message: &MailMessageObject,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let command = if destination_source == "local" {
            if message.backend_location().is_some() {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "online message to local import",
                });
            }
            if message.id().contains("::copy::") {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "local copy of a copy",
                });
            }
            if message.folder_id().eq_ignore_ascii_case(destination_folder) {
                return Ok(true);
            }
            MailCommand::copy_local(message.id(), destination_folder.to_string())
        } else {
            let Some(location) = message.backend_location() else {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "local import to a Graph account",
                });
            };
            if location.source_uid != destination_source {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "different online account",
                });
            }
            if !is_graph_backend_location(Some(&location)) {
                return Err(MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "copying for this account (pending Linux signoff)",
                });
            }
            // A Graph copy intentionally remains allowed in the same folder;
            // Outlook creates a distinct message resource in that case.
            MailCommand::copy_remote(message.id(), location, destination_folder.to_string())
        };

        self.execute_mail_command(command)?;
        Ok(true)
    }

    /// Move a message by ID to destination, updating unread counters and showing a toast.
    pub(crate) fn move_message_by_id_to(
        &self,
        message_id: &str,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let Some(message) = self.find_message_by_id(message_id) else {
            return Ok(false);
        };
        let res = self.move_message_to(&message, destination_source, destination_folder)?;
        if res {
            self.refresh_unread_counters();
            let target_display = if destination_source == "local" {
                Self::local_folder_display_label(destination_folder)
            } else {
                destination_folder.to_string()
            };
            self.show_toast(&gettext("Message moved to “{target}”").replace("{target}", &target_display));
        }
        Ok(res)
    }

    /// Copy a message by ID to destination, updating unread counters and showing a toast.
    pub(crate) fn copy_message_by_id_to(
        &self,
        message_id: &str,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let Some(message) = self.find_message_by_id(message_id) else {
            return Ok(false);
        };
        let res = self.copy_message_to(&message, destination_source, destination_folder)?;
        if res {
            self.refresh_unread_counters();
            let target_display = if destination_source == "local" {
                Self::local_folder_display_label(destination_folder)
            } else {
                destination_folder.to_string()
            };
            self.show_toast(&gettext("Message copied to “{target}”").replace("{target}", &target_display));
        }
        Ok(res)
    }

    fn move_selected_to(
        &self,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_moved = false;
        for message in messages {
            if self.move_message_to(&message, destination_source, destination_folder)? {
                any_moved = true;
            }
        }
        Ok(any_moved)
    }

    fn copy_selected_to(
        &self,
        destination_source: &str,
        destination_folder: &str,
    ) -> Result<bool, MailOperationError> {
        let messages = self.selected_messages();
        if messages.is_empty() {
            return Ok(false);
        }
        let mut any_copied = false;
        for message in messages {
            if self.copy_message_to(&message, destination_source, destination_folder)? {
                any_copied = true;
            }
        }
        Ok(any_copied)
    }

    fn execute_mail_command(&self, command: MailCommand) -> Result<(), MailOperationError> {
        if self.imp().mail_batch_running.get() {
            return Err(MailOperationError::Busy {
                operation: command.operation_kind(),
                message: "laufender Mehrfachauswahl".to_string(),
            });
        }
        let description = command.description().to_string();
        let op_kind = command.operation_kind();
        let prepared = self.imp().mail_operation_coordinator.prepare(command)?;
        let context = prepared.context();
        let operation_id = context.id().get();
        self.imp()
            .mail_operation_cancellations
            .borrow_mut()
            .insert(operation_id, prepared.cancellation());
        self.imp()
            .mail_operations_active
            .set(self.imp().mail_operations_active.get().saturating_add(1));
        self.update_undelete_action();

        self.clear_operation_error();
        if let Some(state) = self.imp().message_state.borrow().as_ref() {
            let localized = gettext(&description);
            state.set_label(&format!("{localized} …"));
        }

        let worker_scope = self.mail_worker_ui_scope();
        let (sender, receiver) = async_channel::bounded(1);
        let store_config = mail_store_worker_config_from_main_thread();
        std::thread::spawn(move || {
            let operations = MailOperationsService::new_worker_safe(store_config);
            let result = prepared.run(&operations);
            let _ = sender.send_blocking(result);
        });

        let page = self.downgrade();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page.upgrade() else {
                return;
            };
            page.imp()
                .mail_operation_cancellations
                .borrow_mut()
                .remove(&operation_id);
            page.imp()
                .mail_operations_active
                .set(page.imp().mail_operations_active.get().saturating_sub(1));

            let scope_is_current = page.mail_worker_ui_scope_is_current(&worker_scope);

            match result {
                Ok(Ok(completed)) => {
                    let cancellation_requested = completed.cancellation_requested();
                    completed.commit(&mut page.imp().mail_commands.borrow_mut());
                    page.imp()
                        .mail_history_generation
                        .set(page.imp().mail_history_generation.get().saturating_add(1));
                    page.persist_mail_history_async();
                    if scope_is_current {
                        page.clear_operation_error();
                        match op_kind {
                            crate::services::mail_operations_service::MailOperationKind::SetMessageState
                            | crate::services::mail_operations_service::MailOperationKind::MarkImportant
                            | crate::services::mail_operations_service::MailOperationKind::MarkNotImportant
                            | crate::services::mail_operations_service::MailOperationKind::SetLabel
                            | crate::services::mail_operations_service::MailOperationKind::SetFollowUp => {
                                page.queue_mail_table_draw();
                            }
                            _ => {
                                page.refresh_mail();
                            }
                        }
                        if let Some(state) = page.imp().message_state.borrow().as_ref() {
                            let status = if cancellation_requested {
                                gettext("Operation has already completed on the server")
                            } else {
                                gettext("{description} completed").replace("{description}", &description)
                            };
                            state.set_label(&status);
                        }
                    }
                }
                Ok(Err(error)) => {
                    if scope_is_current {
                        page.report_operation_error(&description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &description).replace("{error}", &error.to_string()));
                        match op_kind {
                            crate::services::mail_operations_service::MailOperationKind::SetMessageState
                            | crate::services::mail_operations_service::MailOperationKind::MarkImportant
                            | crate::services::mail_operations_service::MailOperationKind::MarkNotImportant
                            | crate::services::mail_operations_service::MailOperationKind::SetLabel
                            | crate::services::mail_operations_service::MailOperationKind::SetFollowUp => {
                                page.queue_mail_table_draw();
                            }
                            _ => {
                                page.refresh_mail();
                            }
                        }
                    }
                }
                Err(_) => {
                    let error = MailOperationError::Io(std::io::Error::other(
                        "Mail worker terminated unexpectedly",
                    ));
                    if scope_is_current {
                        page.report_operation_error(&description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &description).replace("{error}", &error.to_string()));
                        page.refresh_mail();
                    }
                }
            }
            page.update_undelete_action();
        });
        Ok(())
    }

    fn execute_mail_batch(
        &self,
        commands: Vec<MailCommand>,
        description: &str,
    ) -> Result<usize, MailOperationError> {
        let Some(first) = commands.first() else {
            return Ok(0);
        };
        let operation = first.operation_kind();
        if self.imp().mail_batch_running.get() || self.imp().mail_operations_active.get() > 0 {
            return Err(MailOperationError::Busy {
                operation,
                message: "another mail action".to_string(),
            });
        }

        let count = commands.len();
        let context = MailOperationContext::new();
        let operation_id = context.id().get();
        self.imp().mail_batch_running.set(true);
        self.update_undelete_action();
        self.imp()
            .mail_operation_cancellations
            .borrow_mut()
            .insert(operation_id, context.cancellation());
        self.clear_operation_error();
        if let Some(state) = self.imp().message_state.borrow().as_ref() {
            let localized = gettext(description);
            state.set_label(&format!("{localized} …"));
        }

        let worker_scope = self.mail_worker_ui_scope();
        let (sender, receiver) = async_channel::bounded(1);
        let store_config = mail_store_worker_config_from_main_thread();
        std::thread::spawn(move || {
            let operations = MailOperationsService::new_worker_safe(store_config);
            let result =
                MailCommandStack::execute_batch_for_worker(&operations, commands, &context);
            let _ = sender.send_blocking(result);
        });

        let page = self.downgrade();
        let description = description.to_string();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page.upgrade() else {
                return;
            };
            page.imp().mail_batch_running.set(false);
            page.imp()
                .mail_operation_cancellations
                .borrow_mut()
                .remove(&operation_id);

            let scope_is_current = page.mail_worker_ui_scope_is_current(&worker_scope);

            match result {
                Ok(Ok(completed)) => {
                    let applied = completed.len();
                    completed.commit(&mut page.imp().mail_commands.borrow_mut());
                    page.imp()
                        .mail_history_generation
                        .set(page.imp().mail_history_generation.get().saturating_add(1));
                    page.persist_mail_history_async();
                    if scope_is_current {
                        page.clear_operation_error();
                        page.clear_batch_selection();
                        match operation {
                            crate::services::mail_operations_service::MailOperationKind::SetMessageState
                            | crate::services::mail_operations_service::MailOperationKind::MarkImportant
                            | crate::services::mail_operations_service::MailOperationKind::MarkNotImportant
                            | crate::services::mail_operations_service::MailOperationKind::SetLabel
                            | crate::services::mail_operations_service::MailOperationKind::SetFollowUp => {
                                page.queue_mail_table_draw();
                            }
                            _ => {
                                page.refresh_mail();
                            }
                        }
                        if let Some(state) = page.imp().message_state.borrow().as_ref() {
                            state.set_label(&gettext("{description}: {count} completed").replace("{description}", &description).replace("{count}", &applied.to_string()));
                        }
                    }
                }
                Ok(Err(error)) => {
                    if scope_is_current {
                        page.report_operation_error(&description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &description).replace("{error}", &error.to_string()));
                        match operation {
                            crate::services::mail_operations_service::MailOperationKind::SetMessageState
                            | crate::services::mail_operations_service::MailOperationKind::MarkImportant
                            | crate::services::mail_operations_service::MailOperationKind::MarkNotImportant
                            | crate::services::mail_operations_service::MailOperationKind::SetLabel
                            | crate::services::mail_operations_service::MailOperationKind::SetFollowUp => {
                                page.queue_mail_table_draw();
                            }
                            _ => {
                                page.refresh_mail();
                            }
                        }
                    }
                }
                Err(_) => {
                    let error = MailOperationError::Io(std::io::Error::other(
                        "Mail batch worker terminated unexpectedly",
                    ));
                    if scope_is_current {
                        page.report_operation_error(&description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &description).replace("{error}", &error.to_string()));
                        page.refresh_mail();
                    }
                }
            }
            page.update_undelete_action();
        });
        Ok(count)
    }

    fn execute_history_action(
        &self,
        undo: bool,
        operation: crate::services::mail_operations_service::MailOperationKind,
    ) -> Result<(), MailOperationError> {
        if self.imp().mail_batch_running.get() || self.imp().mail_operations_active.get() > 0 {
            return Err(MailOperationError::Busy {
                operation,
                message: "another mail action".to_string(),
            });
        }

        let description = if undo { "Undo" } else { "Redo" };
        let history = self.imp().mail_commands.borrow().clone();
        let context = MailOperationContext::new();
        let operation_id = context.id().get();
        self.imp().mail_batch_running.set(true);
        self.update_undelete_action();
        self.imp()
            .mail_operation_cancellations
            .borrow_mut()
            .insert(operation_id, context.cancellation());
        self.clear_operation_error();
        if let Some(state) = self.imp().message_state.borrow().as_ref() {
            let localized = gettext(description);
            state.set_label(&format!("{localized} …"));
        }

        let worker_scope = self.mail_worker_ui_scope();
        let (sender, receiver) = async_channel::bounded(1);
        let store_config = mail_store_worker_config_from_main_thread();
        std::thread::spawn(move || {
            let operations = MailOperationsService::new_worker_safe(store_config);
            let result = MailCommandStack::execute_history_action_for_worker(
                history,
                &operations,
                undo,
                operation,
                &context,
            )
            .map(|completed| {
                let (history, command) = completed.into_parts();
                history.persist_snapshot();
                (history, command)
            });
            let _ = sender.send_blocking(result);
        });

        let page = self.downgrade();
        glib::spawn_future_local(async move {
            let result = receiver.recv().await;
            let Some(page) = page.upgrade() else {
                return;
            };
            page.imp().mail_batch_running.set(false);
            page.imp()
                .mail_operation_cancellations
                .borrow_mut()
                .remove(&operation_id);

            let scope_is_current = page.mail_worker_ui_scope_is_current(&worker_scope);

            match result {
                Ok(Ok((history, Some(command)))) => {
                    page.imp().mail_commands.replace(history);
                    page.imp()
                        .mail_history_generation
                        .set(page.imp().mail_history_generation.get().saturating_add(1));
                    tracing::info!(
                        operation = command.description(),
                        undo,
                        "Mail history action confirmed"
                    );
                    if scope_is_current {
                        page.clear_operation_error();
                        page.refresh_mail();
                        if let Some(state) = page.imp().message_state.borrow().as_ref() {
                            state.set_label(&gettext("{description} completed").replace("{description}", &gettext(description)));
                        }
                    }
                }
                Ok(Ok((history, None))) => {
                    page.imp().mail_commands.replace(history);
                    if scope_is_current {
                        if let Some(state) = page.imp().message_state.borrow().as_ref() {
                            state.set_label(&gettext("Nothing to {description}").replace("{description}", &gettext(description).to_lowercase()));
                        }
                    }
                }
                Ok(Err(error)) => {
                    if scope_is_current {
                        page.report_operation_error(description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &gettext(description)).replace("{error}", &error.to_string()));
                        page.refresh_mail();
                    }
                }
                Err(_) => {
                    let error = MailOperationError::Io(std::io::Error::other(
                        "Mail history worker terminated unexpectedly",
                    ));
                    if scope_is_current {
                        page.report_operation_error(description, &error);
                        page.show_toast(&gettext("{description} not possible: {error}").replace("{description}", &gettext(description)).replace("{error}", &error.to_string()));
                        page.refresh_mail();
                    }
                }
            }
            page.update_undelete_action();
        });
        Ok(())
    }

    fn selected_batch_messages(&self) -> Vec<MailMessageObject> {
        let selected_ids = self.imp().batch_selection.borrow().clone();
        let Some(store) = self.imp().message_store.borrow().as_ref().cloned() else {
            return Vec::new();
        };
        (0..store.n_items())
            .filter_map(|index| store.item(index).and_downcast::<MailMessageObject>())
            .filter(|message| selected_ids.contains(&message.id()))
            .collect()
    }

    pub fn select_all_visible_messages(&self) -> usize {
        let Some(store) = self.imp().message_store.borrow().as_ref().cloned() else {
            return 0;
        };
        let query = self
            .imp()
            .search_query
            .borrow()
            .as_ref()
            .map(|query| query.borrow().clone())
            .unwrap_or_default();
        let folder_selection = self
            .imp()
            .folder_selection
            .borrow()
            .as_ref()
            .map(|selection| selection.borrow().clone())
            .unwrap_or_default();
        let message_filter = self
            .imp()
            .message_filter_state
            .borrow()
            .as_ref()
            .map(|filter| filter.get())
            .unwrap_or(MessageFilter::All);

        let search_scope = self.imp().search_scope.get();
        let mut batch_selection = self.imp().batch_selection.borrow_mut();
        for index in 0..store.n_items() {
            let Some(message) = store.item(index).and_downcast::<MailMessageObject>() else {
                continue;
            };
            if message_matches_filter(
                &message,
                &query,
                message_filter,
                &folder_selection,
                search_scope,
            ) {
                batch_selection.insert(message.id());
            }
        }
        let count = batch_selection.len();
        drop(batch_selection);

        if let Some(selection) = self.active_selection() {
            selection.select_all();
            self.queue_mail_table_draw();
        }
        self.update_batch_action_bar();
        count
    }

    fn update_batch_action_bar(&self) {
        let count = self.imp().batch_selection.borrow().len();
        if let Some(label) = self.imp().batch_action_label.borrow().as_ref() {
            let count_str = ngettext("{count} selected", "{count} selected", count as u32).replace("{count}", &count.to_string());
            label.set_label(&count_str);
        }
        if let Some(bar) = self.imp().batch_action_bar.borrow().as_ref() {
            bar.set_visible(count > 0);
        }
        self.update_undelete_action();
    }

    fn clear_operation_error(&self) {
        if let Some(state) = self.imp().message_state.borrow().as_ref() {
            state.remove_css_class("error");
        }
    }

    fn report_operation_error(&self, action: &str, error: &MailOperationError) {
        if let Some(state) = self.imp().message_state.borrow().as_ref() {
            state.add_css_class("error");
            state.set_label(&format!("{action}: {error}"));
        }
    }

    fn clear_batch_selection(&self) {
        self.imp().batch_selection.borrow_mut().clear();
        if let Some(store) = self.imp().message_store.borrow().as_ref() {
            let count = store.n_items();
            if count > 0 {
                store.items_changed(0, count, count);
            }
        }
        self.update_batch_action_bar();
    }

    fn mark_batch_read(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        let commands = messages
            .iter()
            .filter(|message| message.is_unread())
            .map(|message| {
                MailCommand::set_message_state(
                    message.id(),
                    message.backend_location(),
                    true,
                    message.is_flagged(),
                    false,
                    message.is_flagged(),
                )
            })
            .collect::<Vec<_>>();
        let count = commands.len();
        if count > 0 {
            self.execute_mail_batch(commands, &gettext("Mark as read"))?;
        }
        Ok(())
    }

    fn mark_batch_unread(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        let commands = messages
            .iter()
            .filter(|message| !message.is_unread())
            .map(|message| {
                MailCommand::set_message_state(
                    message.id(),
                    message.backend_location(),
                    message.is_unread(),
                    message.is_flagged(),
                    true,
                    message.is_flagged(),
                )
            })
            .collect::<Vec<_>>();
        let count = commands.len();
        if count > 0 {
            self.execute_mail_batch(commands, &gettext("Mark as unread"))?;
        }
        Ok(())
    }

    fn toggle_batch_flagged(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        if messages.iter().any(|message| {
            message
                .backend_location()
                .as_ref()
                .is_some_and(|location| is_graph_backend_location(Some(location)))
        }) {
            return Err(MailOperationError::Unsupported {
                operation:
                    crate::services::mail_operations_service::MailOperationKind::SetMessageState,
                backend: "Graph (please use separate follow-up flag)",
            });
        }
        let next_flagged = messages.iter().any(|message| !message.is_flagged());
        let commands = messages
            .iter()
            .filter(|message| message.is_flagged() != next_flagged)
            .map(|message| {
                MailCommand::set_message_state(
                    message.id(),
                    message.backend_location(),
                    message.is_unread(),
                    message.is_flagged(),
                    message.is_unread(),
                    next_flagged,
                )
            })
            .collect::<Vec<_>>();
        let count = commands.len();
        if count > 0 {
            self.execute_mail_batch(commands, &gettext("Change flag"))?;
        }
        Ok(())
    }

    fn toggle_batch_important(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        if messages.iter().any(|message| {
            message
                .backend_location()
                .as_ref()
                .is_some_and(|location| !is_graph_backend_location(Some(location)))
        }) {
            return Err(MailOperationError::Unsupported {
                operation:
                    crate::services::mail_operations_service::MailOperationKind::MarkImportant,
                backend: "importance flag for this account (pending Linux signoff)",
            });
        }
        let next_important = messages.iter().any(|message| !message.is_important());
        let commands = messages
            .iter()
            .filter(|message| message.is_important() != next_important)
            .map(|message| {
                message
                    .backend_location()
                    .map(|location| {
                        MailCommand::set_important(
                            message.id(),
                            location,
                            message.is_important(),
                            next_important,
                        )
                    })
                    .unwrap_or_else(|| {
                        MailCommand::set_important_local(
                            message.id(),
                            message.is_important(),
                            next_important,
                        )
                    })
            })
            .collect::<Vec<_>>();
        let count = commands.len();
        if count > 0 {
            self.execute_mail_batch(commands, &gettext("Change importance"))?;
        }
        Ok(())
    }

    fn archive_batch(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        let commands = messages
            .iter()
            .map(|message| {
                message
                    .backend_location()
                    .map(|location| MailCommand::archive(message.id(), location))
                    .unwrap_or_else(|| {
                        MailCommand::archive_local(message.id(), message.folder_id())
                    })
            })
            .collect::<Vec<_>>();
        self.execute_mail_batch(commands, &gettext("Archive messages"))?;
        Ok(())
    }

    fn mark_batch_junk(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        let commands = messages
            .iter()
            .map(|message| match message.backend_location() {
                Some(location) => {
                    MailCommand::set_junk(message.id(), location, message_is_junk(message), true)
                }
                None => MailCommand::set_junk_local(message.id(), message.folder_id()),
            })
            .collect::<Vec<_>>();
        self.execute_mail_batch(commands, &gettext("Mark as junk"))?;
        Ok(())
    }

    fn mark_batch_not_junk(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self
            .selected_batch_messages()
            .into_iter()
            .filter(message_is_junk)
            .collect::<Vec<_>>();
        let commands = messages
            .iter()
            .map(|message| {
                message
                    .backend_location()
                    .map(|location| MailCommand::set_junk(message.id(), location, true, false))
                    .unwrap_or_else(|| MailCommand::clear_junk_local(message.id()))
            })
            .collect::<Vec<_>>();
        self.execute_mail_batch(commands, &gettext("Remove junk status"))?;
        Ok(())
    }

    fn delete_batch(&self) -> Result<(), MailOperationError> {
        self.clear_operation_error();
        let messages = self.selected_batch_messages();
        let commands = messages
            .iter()
            .map(|message| {
                message
                    .backend_location()
                    .map(|location| MailCommand::delete(message.id(), location))
                    .unwrap_or_else(|| MailCommand::delete_local(message.id()))
            })
            .collect::<Vec<_>>();
        self.execute_mail_batch(commands, &gettext("Delete messages"))?;
        Ok(())
    }

    fn folder_destinations(&self) -> Vec<MoveDestination> {
        let messages = self.selected_batch_messages();
        self.folder_destinations_for_messages(&messages)
    }

    fn folder_destinations_for_messages(
        &self,
        messages: &[MailMessageObject],
    ) -> Vec<MoveDestination> {
        let mut destinations = Vec::new();
        let single_local_message = messages.len() == 1 && messages[0].backend_location().is_none();
        let single_remote_source = (messages.len() == 1).then(|| {
            messages[0]
                .backend_location()
                .map(|location| location.source_uid)
        });
        if let Some(folder_index) = self.imp().dynamic_folder_index.borrow().as_ref().cloned() {
            for folder in folder_index.borrow().values() {
                let (Some(source_uid), Some(folder_name)) =
                    (folder.source_uid(), folder.folder_name())
                else {
                    continue;
                };
                if single_local_message
                    || single_remote_source
                        .as_ref()
                        .is_some_and(|source| source.as_deref() != Some(source_uid.as_str()))
                {
                    continue;
                }
                if !folder.selectable() {
                    continue;
                }
                destinations.push(MoveDestination {
                    source_uid,
                    folder_name,
                    label: folder.name(),
                });
            }
        }

        let has_local_messages = messages
            .iter()
            .any(|message| message.backend_location().is_none());
        if has_local_messages {
            for (folder_name, label) in [
                ("inbox", gettext("Local Inbox")),
                ("sent", gettext("Local · Sent")),
                ("drafts", gettext("Local · Drafts")),
                ("trash", gettext("Local Trash")),
                ("archive", gettext("Local Archive")),
                ("junk", gettext("Local Junk")),
            ] {
                destinations.push(MoveDestination {
                    source_uid: "local".to_string(),
                    folder_name: folder_name.to_string(),
                    label,
                });
            }
            for folder_id in self
                .imp()
                .local_folder_ids
                .borrow()
                .iter()
                .filter(|folder_id| folder_id.starts_with("custom:"))
            {
                destinations.push(MoveDestination {
                    source_uid: "local".to_string(),
                    folder_name: folder_id.clone(),
                    label: format!("Lokal · {}", Self::local_folder_label(folder_id)),
                });
            }
        }

        destinations.sort_by(|left, right| {
            left.label
                .cmp(&right.label)
                .then_with(|| left.source_uid.cmp(&right.source_uid))
                .then_with(|| left.folder_name.cmp(&right.folder_name))
        });
        destinations.dedup_by(|left, right| {
            left.source_uid == right.source_uid && left.folder_name == right.folder_name
        });
        destinations
    }

    fn copy_folder_destinations(&self) -> Vec<MoveDestination> {
        let messages = self.selected_batch_messages();
        self.copy_folder_destinations_for_messages(&messages)
    }

    fn graph_copy_source_for_messages(&self, messages: &[MailMessageObject]) -> Option<String> {
        let mut source_uid = None;
        for message in messages {
            let location = message.backend_location()?;
            if !is_graph_backend_location(Some(&location)) {
                return None;
            }
            match source_uid.as_deref() {
                Some(existing) if existing != location.source_uid => return None,
                None => source_uid = Some(location.source_uid),
                _ => {}
            }
        }
        source_uid
    }

    fn copy_folder_destinations_for_messages(
        &self,
        messages: &[MailMessageObject],
    ) -> Vec<MoveDestination> {
        let graph_source = self.graph_copy_source_for_messages(messages);
        self.folder_destinations_for_messages(messages)
            .into_iter()
            .filter(|destination| {
                destination.source_uid == "local"
                    || graph_source.as_deref() == Some(destination.source_uid.as_str())
            })
            .collect()
    }

    fn move_batch_to(&self, destination_source: &str, destination_folder: &str) {
        let messages = self.selected_batch_messages();
        let has_local = messages
            .iter()
            .any(|message| message.backend_location().is_none());
        let has_remote = messages
            .iter()
            .any(|message| message.backend_location().is_some());
        if has_local && has_remote {
            self.report_operation_error(
                &gettext("Move not possible"),
                &MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Move,
                    backend: "mixed local/account selection",
                },
            );
            return;
        }

        let commands = if destination_source == "local" {
            messages
                .iter()
                .filter(|message| message.backend_location().is_none())
                .map(|message| {
                    MailCommand::move_local(
                        message.id(),
                        message.folder_id(),
                        destination_folder.to_string(),
                    )
                })
                .collect::<Vec<_>>()
        } else {
            messages
                .iter()
                .filter_map(|message| {
                    let location = message.backend_location()?;
                    (location.source_uid == destination_source).then(|| {
                        MailCommand::move_to(message.id(), location, destination_folder.to_string())
                    })
                })
                .collect::<Vec<_>>()
        };

        if commands.is_empty() {
            self.report_operation_error(
                &gettext("Move not possible"),
                &MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Move,
                    backend: "no common account",
                },
            );
            return;
        }

        let result = self.execute_mail_batch(commands, &gettext("Move messages"));
        match result {
            Ok(_) => {}
            Err(error) => {
                self.report_operation_error(&gettext("Move not possible"), &error);
            }
        }
    }

    fn copy_batch_to(&self, destination_source: &str, destination_folder: &str) {
        let messages = self.selected_batch_messages();
        let has_local = messages
            .iter()
            .any(|message| message.backend_location().is_none());
        let has_remote = messages
            .iter()
            .any(|message| message.backend_location().is_some());
        if has_local && has_remote {
            self.report_operation_error(
                &gettext("Copy not possible"),
                &MailOperationError::Unsupported {
                    operation: crate::services::mail_operations_service::MailOperationKind::Copy,
                    backend: "mixed local/remote selection",
                },
            );
            return;
        }

        let commands = if destination_source == "local" {
            if has_remote {
                self.report_operation_error(
                    &gettext("Copy not possible"),
                    &MailOperationError::Unsupported {
                        operation:
                            crate::services::mail_operations_service::MailOperationKind::Copy,
                        backend: "online message to local import",
                    },
                );
                return;
            }
            if messages
                .iter()
                .any(|message| message.id().contains("::copy::"))
            {
                self.report_operation_error(
                    &gettext("Copy not possible"),
                    &MailOperationError::Unsupported {
                        operation:
                            crate::services::mail_operations_service::MailOperationKind::Copy,
                        backend: "local copy of a copy",
                    },
                );
                return;
            }
            messages
                .iter()
                .filter(|message| !message.folder_id().eq_ignore_ascii_case(destination_folder))
                .map(|message| {
                    MailCommand::copy_local(message.id(), destination_folder.to_string())
                })
                .collect::<Vec<_>>()
        } else {
            let Some(source_uid) = self.graph_copy_source_for_messages(&messages) else {
                self.report_operation_error(
                    &gettext("Copy not possible"),
                    &MailOperationError::Unsupported {
                        operation:
                            crate::services::mail_operations_service::MailOperationKind::Copy,
                        backend: if has_remote {
                            "copying for this account (pending Linux signoff)"
                        } else {
                            "local import to a Graph account"
                        },
                    },
                );
                return;
            };
            if source_uid != destination_source {
                self.report_operation_error(
                    &gettext("Copy not possible"),
                    &MailOperationError::Unsupported {
                        operation:
                            crate::services::mail_operations_service::MailOperationKind::Copy,
                        backend: "different online account",
                    },
                );
                return;
            }
            messages
                .iter()
                .filter_map(|message| {
                    message.backend_location().map(|location| {
                        MailCommand::copy_remote(
                            message.id(),
                            location,
                            destination_folder.to_string(),
                        )
                    })
                })
                .collect::<Vec<_>>()
        };
        if commands.is_empty() {
            self.clear_batch_selection();
            if let Some(state) = self.imp().message_state.borrow().as_ref() {
                state.set_label(&gettext("No new copy needed"));
            }
            return;
        }

        let result = self.execute_mail_batch(commands, &gettext("Copy messages"));
        match result {
            Ok(_) => {}
            Err(error) => {
                self.report_operation_error(&gettext("Copy not possible"), &error);
            }
        }
    }

    // ── Private: Build Sidebar (Folder Tree) ────────────────────────────

    fn build_sidebar(
        &self,
    ) -> (
        gtk::Box,
        gio::ListStore,
        gtk::Label,
        gtk::Box,
        gtk::ListBox,
        gtk::ListBox,
    ) {
        let source_store = gio::ListStore::new::<EdsSourceObject>();
        let source_selection = gtk::SingleSelection::new(Some(source_store.clone()));
        source_selection.set_autoselect(false);
        source_selection.set_can_unselect(true);
        let source_factory = gtk::SignalListItemFactory::new();

        source_factory.connect_setup(|_, list_item| {
            let list_item = list_item
                .downcast_ref::<gtk::ListItem>()
                .expect("Expected ListItem");

            let row = gtk::Box::builder()
                .orientation(gtk::Orientation::Horizontal)
                .spacing(4)
                .margin_start(4)
                .margin_end(4)
                .css_classes(vec!["mail-sidebar-row"])
                .build();

            let title = gtk::Label::builder()
                .halign(gtk::Align::Start)
                .hexpand(true)
                .ellipsize(pango::EllipsizeMode::End)
                .build();
            row.append(&title);
            list_item.set_child(Some(&row));
        });

        source_factory.connect_bind(|_, list_item| {
            let list_item = list_item
                .downcast_ref::<gtk::ListItem>()
                .expect("Expected ListItem");
            let source = list_item
                .item()
                .and_downcast::<EdsSourceObject>()
                .expect("Expected EdsSourceObject");
            let row = list_item
                .child()
                .and_downcast::<gtk::Box>()
                .expect("Expected source row");

            if let Some(title) = row.last_child().and_downcast::<gtk::Label>() {
                let display_name = Self::localize_source_name(&source.display_name());
                title.set_label(&display_name);
                title.set_tooltip_text(Some(&format!(
                    "{} · {}",
                    display_name,
                    if source.enabled() {
                        gettext("active")
                    } else {
                        gettext("Account not available")
                    }
                )));
            }
            row.set_sensitive(source.enabled());
        });

        let source_view = gtk::ListView::builder()
            .model(&source_selection)
            .factory(&source_factory)
            .css_classes(vec!["navigation-sidebar"])
            .visible(false)
            .build();

        let page_for_source = self.downgrade();
        source_selection.connect_selected_item_notify(move |selection| {
            if page_for_source
                .upgrade()
                .is_some_and(|page| page.imp().saved_search_applying.get())
            {
                return;
            }
            if let Some(source) = selection.selected_item().and_downcast::<EdsSourceObject>() {
                if !source.enabled() {
                    tracing::debug!(
                        uid = %source.uid(),
                        display_name = %source.display_name(),
                        "Ignoring selection of a source without an active backend"
                    );
                    return;
                }
                tracing::debug!(
                    uid = %source.uid(),
                    display_name = %source.display_name(),
                    "EDS mail source selected"
                );
                if let Some(page) = page_for_source.upgrade() {
                    let initial_folder = FolderSelection::configured_initial();
                    if let Some(folder_selection) = page.imp().folder_selection.borrow().as_ref() {
                        folder_selection.replace(initial_folder.clone());
                    }
                    page.select_folder_row(&initial_folder);
                    if let Some(filter) = page.imp().message_filter.borrow().as_ref() {
                        filter.changed(gtk::FilterChange::Different);
                    }
                    if let Some(root) = page.root().and_downcast::<crate::window::EvolutionWindow>()
                    {
                        root.update_folder_subscriptions_action_for_current_view();
                    }
                    page.start_mail_load(
                        MailLoadRequest {
                            source_uid: Some(source.uid()),
                            folder_name: None,
                            offset: 0,
                            max_messages_per_folder: configured_mail_page_limit(),
                            graph_cursors: HashMap::new(),
                        },
                        true,
                    );
                }
            }
        });
        self.imp()
            .source_selection
            .replace(Some(source_selection.clone()));

        let folder_list = gtk::ListBox::new();
        folder_list.set_selection_mode(gtk::SelectionMode::Single);
        folder_list.add_css_class("navigation-sidebar");
        folder_list.set_margin_start(0);

        let all_str = crate::i18n::gettext("All Messages");
        let inbox_str = crate::i18n::gettext("Inbox");
        let sent_str = crate::i18n::gettext("Sent");
        let drafts_str = crate::i18n::gettext("Drafts");
        let trash_str = crate::i18n::gettext("Trash");
        let archive_str = crate::i18n::gettext("Archive");
        let junk_str = crate::i18n::gettext("Junk");

        let folders = [
            ("all", "mail-unread-symbolic", all_str.as_str(), ""),
            ("inbox", "mail-inbox-symbolic", inbox_str.as_str(), ""),
            ("sent", "mail-send-symbolic", sent_str.as_str(), ""),
            ("drafts", "mail-drafts-symbolic", drafts_str.as_str(), ""),
            ("trash", "user-trash-symbolic", trash_str.as_str(), ""),
            ("archive", "folder-symbolic", archive_str.as_str(), ""),
            ("spam", "mail-mark-junk-symbolic", junk_str.as_str(), ""),
        ];

        for (id, icon, label, badge) in folders {
            let row = Self::create_folder_row(id, icon, label, badge);
            if id != "all" {
                self.install_local_folder_drag_and_drop(&row, id);
            }
            folder_list.append(&row);
        }

        let local_folder_click = gtk::GestureClick::builder()
            .button(3)
            .propagation_phase(gtk::PropagationPhase::Capture)
            .build();
        let list_weak = folder_list.downgrade();
        let page_for_local_folder_menu = self.downgrade();
        local_folder_click.connect_pressed(move |gesture, _, x, y| {
            gesture.set_state(gtk::EventSequenceState::Claimed);
            let (Some(page), Some(list)) =
                (page_for_local_folder_menu.upgrade(), list_weak.upgrade())
            else {
                return;
            };
            let Some(row) = list.row_at_y(y as i32) else {
                return;
            };
            let Some(target) = Self::folder_row_data(&row)
                .and_then(|data| popup_folder_target(data.selection(), true))
            else {
                return;
            };
            page.present_folder_context_menu(&list, x, y, target);
        });
        folder_list.add_controller(local_folder_click);

        let local_folder_long_press = gtk::GestureLongPress::builder()
            .propagation_phase(gtk::PropagationPhase::Capture)
            .build();
        let list_weak_lp = folder_list.downgrade();
        let page_for_local_folder_lp = self.downgrade();
        local_folder_long_press.connect_pressed(move |gesture, x, y| {
            gesture.set_state(gtk::EventSequenceState::Claimed);
            let (Some(page), Some(list)) =
                (page_for_local_folder_lp.upgrade(), list_weak_lp.upgrade())
            else {
                return;
            };
            let Some(row) = list.row_at_y(y as i32) else {
                return;
            };
            let Some(target) = Self::folder_row_data(&row)
                .and_then(|data| popup_folder_target(data.selection(), true))
            else {
                return;
            };
            page.present_folder_context_menu(&list, x, y, target);
        });
        folder_list.add_controller(local_folder_long_press);

        let dynamic_folder_store = gio::ListStore::new::<FolderObject>();
        let dynamic_folder_children =
            Rc::new(RefCell::new(HashMap::<String, gio::ListStore>::new()));
        let dynamic_folder_index = Rc::new(RefCell::new(HashMap::<String, FolderObject>::new()));
        let children_for_dynamic_model = Rc::clone(&dynamic_folder_children);
        let dynamic_tree_model =
            gtk::TreeListModel::new(dynamic_folder_store.clone(), false, false, move |item| {
                let folder = item.downcast_ref::<FolderObject>()?;
                children_for_dynamic_model
                    .borrow()
                    .get(&folder.id())
                    .cloned()
                    .map(|store| store.upcast::<gio::ListModel>())
            });
        let dynamic_folder_selection = gtk::SingleSelection::new(Some(dynamic_tree_model));
        dynamic_folder_selection.set_autoselect(false);
        dynamic_folder_selection.set_can_unselect(true);

        let dynamic_factory = gtk::SignalListItemFactory::new();
        let page_for_dynamic_folder_menu = self.downgrade();
        dynamic_factory.connect_setup(move |_, list_item| {
            let list_item = list_item
                .downcast_ref::<gtk::ListItem>()
                .expect("Expected ListItem");
            let expander = gtk::TreeExpander::new();
            expander.set_indent_for_depth(false);
            expander.set_indent_for_icon(true);
            expander.set_hide_expander(false);
            expander.set_valign(gtk::Align::Center);

            // 0: Folder icon
            let icon = gtk::Image::builder()
                .pixel_size(16)
                .valign(gtk::Align::Center)
                .css_classes(["dim-label"])
                .build();

            // 1: Folder / Account label
            let label = gtk::Label::builder()
                .xalign(0.0)
                .hexpand(true)
                .valign(gtk::Align::Center)
                .ellipsize(pango::EllipsizeMode::End)
                .build();

            // 2: Sync icon (account root only)
            let sync_icon = gtk::Image::builder()
                .icon_name("mail-sync-symbolic")
                .pixel_size(16)
                .valign(gtk::Align::Center)
                .css_classes(["dim-label"])
                .visible(false)
                .build();

            // 3: Badge (unread count)
            let badge = gtk::Label::builder()
                .xalign(1.0)
                .valign(gtk::Align::Center)
                .css_classes(["badge", "numeric"])
                .visible(false)
                .build();

            let row = gtk::Box::builder()
                .orientation(gtk::Orientation::Horizontal)
                .spacing(5)
                .margin_start(0)
                .margin_end(2)
                .margin_top(0)
                .margin_bottom(0)
                .valign(gtk::Align::Center)
                .css_classes(vec!["mail-sidebar-row"])
                .build();

            row.append(&icon);
            row.append(&label);
            row.append(&sync_icon);
            row.append(&badge);

            let right_click = gtk::GestureClick::builder()
                .button(3)
                .propagation_phase(gtk::PropagationPhase::Capture)
                .build();
            let list_item_for_menu = list_item.downgrade();
            let row_for_menu = row.downgrade();
            let page_for_menu = page_for_dynamic_folder_menu.clone();
            right_click.connect_pressed(move |gesture, _, x, y| {
                gesture.set_state(gtk::EventSequenceState::Claimed);
                let (Some(page), Some(list_item), Some(row)) = (
                    page_for_menu.upgrade(),
                    list_item_for_menu.upgrade(),
                    row_for_menu.upgrade(),
                ) else {
                    return;
                };
                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return;
                };
                let Some(folder) = tree_row.item().and_downcast::<FolderObject>() else {
                    return;
                };
                let selection = FolderSelection {
                    folder_id: folder.id(),
                    source_uid: folder.source_uid(),
                    folder_name: folder
                        .folder_name()
                        .filter(|folder_name| !folder_name.trim().is_empty()),
                };
                let Some(target) = popup_folder_target(selection, folder.selectable()) else {
                    return;
                };
                page.present_folder_context_menu(&row, x, y, target);
            });
            row.add_controller(right_click);

            let long_press = gtk::GestureLongPress::builder()
                .propagation_phase(gtk::PropagationPhase::Capture)
                .build();
            let list_item_for_lp = list_item.downgrade();
            let row_for_lp = row.downgrade();
            let page_for_lp = page_for_dynamic_folder_menu.clone();
            long_press.connect_pressed(move |gesture, x, y| {
                gesture.set_state(gtk::EventSequenceState::Claimed);
                let (Some(page), Some(list_item), Some(row)) = (
                    page_for_lp.upgrade(),
                    list_item_for_lp.upgrade(),
                    row_for_lp.upgrade(),
                ) else {
                    return;
                };
                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return;
                };
                let Some(folder) = tree_row.item().and_downcast::<FolderObject>() else {
                    return;
                };
                let selection = FolderSelection {
                    folder_id: folder.id(),
                    source_uid: folder.source_uid(),
                    folder_name: folder
                        .folder_name()
                        .filter(|folder_name| !folder_name.trim().is_empty()),
                };
                let Some(target) = popup_folder_target(selection, folder.selectable()) else {
                    return;
                };
                page.present_folder_context_menu(&row, x, y, target);
            });
            row.add_controller(long_press);

            let click = gtk::GestureClick::builder()
                .button(gtk::gdk::BUTTON_PRIMARY)
                .build();
            let list_item_for_click = list_item.downgrade();
            click.connect_pressed(move |_, n_press, _, _| {
                let Some(list_item) = list_item_for_click.upgrade() else {
                    return;
                };
                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return;
                };
                let is_account_root = tree_row.depth() == 0;
                if is_account_root && tree_row.is_expandable() {
                    tree_row.set_expanded(!tree_row.is_expanded());
                } else if n_press == 2 && tree_row.is_expandable() {
                    tree_row.set_expanded(!tree_row.is_expanded());
                }
            });
            row.add_controller(click);

            let row_weak = row.downgrade();
            let list_item_weak = list_item.downgrade();
            list_item.connect_selected_notify(move |_item| {
                let (Some(row), Some(item)) = (row_weak.upgrade(), list_item_weak.upgrade()) else {
                    return;
                };
                let is_account_root = item
                    .item()
                    .and_downcast::<gtk::TreeListRow>()
                    .map(|r| r.depth() == 0)
                    .unwrap_or(false);
                if item.is_selected() && !is_account_root {
                    row.add_css_class("is-selected");
                } else {
                    row.remove_css_class("is-selected");
                }
            });

            let drag_source = gtk::DragSource::new();
            drag_source.set_actions(gtk::gdk::DragAction::MOVE);
            let list_item_for_drag = list_item.downgrade();
            let list_item_for_drag_begin = list_item.downgrade();
            drag_source.connect_drag_begin(move |_, drag| {
                let Some(list_item) = list_item_for_drag_begin.upgrade() else {
                    return;
                };
                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return;
                };
                let Some(folder) = tree_row.item().and_downcast::<FolderObject>() else {
                    return;
                };
                let chip = create_folder_drag_chip(&folder.name(), Some(&folder.icon_name()));
                let drag_icon = gtk::DragIcon::for_drag(drag);
                drag_icon.set_child(Some(&chip));
            });
            drag_source.connect_prepare(move |_, _, _| {
                let Some(list_item) = list_item_for_drag.upgrade() else {
                    return None;
                };
                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return None;
                };
                let Some(folder) = tree_row.item().and_downcast::<FolderObject>() else {
                    return None;
                };
                if tree_row.depth() == 0 || !folder.selectable() {
                    return None;
                }
                let payload = FolderDragPayload {
                    folder_id: folder.id(),
                    source_uid: folder.source_uid(),
                    folder_name: folder.folder_name(),
                    parent_id: folder.parent_id(),
                    display_name: folder.name(),
                };
                let Ok(json) = serde_json::to_string(&payload) else {
                    return None;
                };
                let content_string = format!("evolution-folder:{json}");
                Some(gtk::gdk::ContentProvider::for_value(
                    &content_string.to_value(),
                ))
            });
            row.add_controller(drag_source);

            let drop_target = gtk::DropTarget::new(
                glib::Type::STRING,
                gtk::gdk::DragAction::MOVE | gtk::gdk::DragAction::COPY,
            );
            drop_target.connect_enter(|_, _, _| {
                gtk::gdk::DragAction::MOVE | gtk::gdk::DragAction::COPY
            });

            let row_for_motion = row.downgrade();
            drop_target.connect_motion(move |_, _, y| {
                let Some(row) = row_for_motion.upgrade() else {
                    return gtk::gdk::DragAction::empty();
                };
                let height = row.height() as f64;
                let threshold = if height > 0.0 { height / 2.0 } else { 12.0 };
                if y < threshold {
                    row.add_css_class("drop-before");
                    row.remove_css_class("drop-after");
                } else {
                    row.add_css_class("drop-after");
                    row.remove_css_class("drop-before");
                }
                gtk::gdk::DragAction::MOVE | gtk::gdk::DragAction::COPY
            });

            let row_for_leave = row.downgrade();
            drop_target.connect_leave(move |_| {
                if let Some(row) = row_for_leave.upgrade() {
                    row.remove_css_class("drop-before");
                    row.remove_css_class("drop-after");
                    row.remove_css_class("drop-into");
                }
            });

            let row_for_drop_action = row.downgrade();
            let list_item_for_drop = list_item.downgrade();
            let page_for_drop = page_for_dynamic_folder_menu.clone();
            drop_target.connect_drop(move |target, value, _, y| {
                let (Some(row), Some(list_item), Some(page)) = (
                    row_for_drop_action.upgrade(),
                    list_item_for_drop.upgrade(),
                    page_for_drop.upgrade(),
                ) else {
                    return false;
                };
                row.remove_css_class("drop-before");
                row.remove_css_class("drop-after");
                row.remove_css_class("drop-into");

                let Ok(payload_str) = value.get::<String>() else {
                    return false;
                };

                let Some(tree_row) = list_item.item().and_downcast::<gtk::TreeListRow>() else {
                    return false;
                };
                let Some(target_folder) = tree_row.item().and_downcast::<FolderObject>() else {
                    return false;
                };

                // Handle dropped message
                if let Some(msg_ids_str) = payload_str.strip_prefix("evolution-message:") {
                    if !target_folder.selectable() {
                        page.show_toast(&gettext("Messages cannot be placed in this folder"));
                        return false;
                    }
                    let target_source = target_folder
                        .source_uid()
                        .unwrap_or_else(|| "local".to_string());
                    let target_folder_name = target_folder
                        .folder_name()
                        .unwrap_or_else(|| target_folder.id());

                    let drop_action = target
                        .current_drop()
                        .map(|d| d.actions())
                        .unwrap_or(gtk::gdk::DragAction::MOVE);
                    let is_copy = drop_action.contains(gtk::gdk::DragAction::COPY)
                        && !drop_action.contains(gtk::gdk::DragAction::MOVE);

                    let mut all_success = true;
                    for msg_id in msg_ids_str.split(',') {
                        let msg_id = msg_id.trim();
                        if msg_id.is_empty() {
                            continue;
                        }
                        let result = if is_copy {
                            page.copy_message_by_id_to(msg_id, &target_source, &target_folder_name)
                        } else {
                            page.move_message_by_id_to(msg_id, &target_source, &target_folder_name)
                        };
                        match result {
                            Ok(success) => {
                                if !success {
                                    all_success = false;
                                }
                            }
                            Err(err) => {
                                page.show_toast(&gettext("Action not possible: {error}").replace("{error}", &err.to_string()));
                                all_success = false;
                            }
                        }
                    }
                    return all_success;
                }

                // Handle dropped folder reordering
                let Some(json) = payload_str.strip_prefix("evolution-folder:") else {
                    return false;
                };
                let Ok(dragged) = serde_json::from_str::<FolderDragPayload>(json) else {
                    return false;
                };

                let height = row.height() as f64;
                let is_before = y < (if height > 0.0 { height / 2.0 } else { 12.0 });

                page.handle_folder_drop_outcome(&dragged, &target_folder, is_before)
            });
            row.add_controller(drop_target);

            expander.set_child(Some(&row));
            list_item.set_child(Some(&expander));
        });
        let page_weak_for_bind = self.downgrade();
        dynamic_factory.connect_bind(move |_, list_item| {
            let list_item = list_item
                .downcast_ref::<gtk::ListItem>()
                .expect("Expected ListItem");
            let tree_row = list_item
                .item()
                .and_downcast::<gtk::TreeListRow>()
                .expect("Expected TreeListRow");
            let folder = tree_row
                .item()
                .and_downcast::<FolderObject>()
                .expect("Expected FolderObject");
            let expander = list_item
                .child()
                .and_downcast::<gtk::TreeExpander>()
                .expect("Expected TreeExpander");
            expander.set_list_row(Some(&tree_row));
            let row = expander
                .child()
                .and_downcast::<gtk::Box>()
                .expect("Expected folder row");
            row.set_margin_start(0);
            let is_account_root = tree_row.depth() == 0;

            list_item.set_selectable(folder.selectable() && !is_account_root);

            if is_account_root {
                expander.add_css_class("account-root-expander");
                row.add_css_class("account-root-row");
                row.remove_css_class("is-selected");
                expander.set_indent_for_depth(false);
                expander.set_indent_for_icon(true);
            } else {
                expander.remove_css_class("account-root-expander");
                row.remove_css_class("account-root-row");
                if list_item.is_selected() {
                    row.add_css_class("is-selected");
                } else {
                    row.remove_css_class("is-selected");
                }
                expander.set_indent_for_depth(true);
                expander.set_indent_for_icon(true);
            }

            // 0: icon
            if let Some(icon) = row.first_child().and_downcast::<gtk::Image>() {
                if is_account_root {
                    if !folder.icon_name().is_empty() {
                        icon.set_visible(true);
                        set_image_icon_with_fallback(&icon, &folder.icon_name(), "system-users-symbolic");
                        icon.set_tooltip_text(Some("Freigegebenes Postfach (Exchange)"));
                    } else {
                        icon.set_visible(false);
                        icon.set_icon_name(None);
                        icon.set_tooltip_text(None);
                    }
                } else {
                    icon.set_visible(true);
                    set_image_icon_with_fallback(&icon, &folder.icon_name(), "folder-symbolic");
                    icon.set_tooltip_text(None);
                }
            }

            // 1: label
            let label_opt = row
                .first_child()
                .and_then(|c| c.next_sibling())
                .and_downcast::<gtk::Label>();
            if let Some(label) = label_opt.as_ref() {
                label.set_label(&folder.name());
                label.set_sensitive(folder.selectable());
                if is_account_root {
                    label.add_css_class("account-heading");
                } else {
                    label.remove_css_class("account-heading");
                }
                if folder.unread_count() > 0 {
                    label.add_css_class("unread-heading");
                } else {
                    label.remove_css_class("unread-heading");
                }
            }

            // 2: sync_icon
            if let Some(sync_icon) = row
                .first_child()
                .and_then(|c| c.next_sibling())
                .and_then(|c| c.next_sibling())
                .and_downcast::<gtk::Image>()
            {
                sync_icon.set_visible(is_account_root);
            }

            // 3: badge
            let badge_opt = row.last_child().and_downcast::<gtk::Label>();
            if let Some(badge) = badge_opt.as_ref() {
                let count = folder.unread_count();
                badge.set_label(&format!("({count})"));
                badge.set_visible(count > 0 && !is_account_root);
            }

            // Connect to counts-changed signal
            if let (Some(label), Some(badge)) = (label_opt, badge_opt) {
                let label_weak = label.downgrade();
                let badge_weak = badge.downgrade();
                let folder_weak = folder.downgrade();
                let handler_id = folder.connect_local("counts-changed", false, move |_| {
                    let (Some(label), Some(badge), Some(folder)) = (
                        label_weak.upgrade(),
                        badge_weak.upgrade(),
                        folder_weak.upgrade(),
                    ) else {
                        return None;
                    };
                    let count = folder.unread_count();
                    if count > 0 {
                        label.add_css_class("unread-heading");
                    } else {
                        label.remove_css_class("unread-heading");
                    }
                    badge.set_label(&format!("({count})"));
                    badge.set_visible(count > 0 && !is_account_root);
                    None
                });
                unsafe {
                    row.set_data("counts-handler", handler_id);
                }
            }

            // Connect to expanded notify signal
            let folder_id = folder.id();
            let page_weak = page_weak_for_bind.clone();
            let expand_handler = tree_row.connect_expanded_notify(move |row| {
                if let Some(page) = page_weak.upgrade() {
                    if page.imp().updating_folder_rows.get() {
                        return;
                    }
                    page.set_dynamic_folder_expanded(&folder_id, row.is_expanded());
                }
            });
            unsafe {
                row.set_data("expand-handler", expand_handler);
            }
        });
        dynamic_factory.connect_unbind(|_, list_item| {
            let list_item = list_item
                .downcast_ref::<gtk::ListItem>()
                .expect("Expected ListItem");
            list_item.set_selectable(true);
            if let Some(expander) = list_item.child().and_downcast::<gtk::TreeExpander>() {
                let row_box = expander.child().and_downcast::<gtk::Box>();
                if let Some(tree_row) = expander.list_row() {
                    if let Some(ref row) = row_box {
                        if let Some(handler_id) =
                            unsafe { row.steal_data::<glib::SignalHandlerId>("expand-handler") }
                        {
                            tree_row.disconnect(handler_id);
                        }
                    }
                    if let Some(folder) = tree_row.item().and_downcast::<FolderObject>() {
                        if let Some(ref row) = row_box {
                            if let Some(handler_id) =
                                unsafe { row.steal_data::<glib::SignalHandlerId>("counts-handler") }
                            {
                                folder.disconnect(handler_id);
                            }
                        }
                    }
                }
                if let Some(ref row) = row_box {
                    row.remove_css_class("is-selected");
                    row.remove_css_class("account-root-row");
                }
                expander.remove_css_class("account-root-expander");
                expander.set_list_row(None);
            }
        });
        let dynamic_folder_view = gtk::ListView::builder()
            .model(&dynamic_folder_selection)
            .factory(&dynamic_factory)
            .css_classes(vec!["navigation-sidebar"])
            .build();
        dynamic_folder_view.set_margin_start(0);

        let page_for_dynamic_activate = self.downgrade();
        dynamic_folder_view.connect_activate(move |_, _| {
            if let Some(page) = page_for_dynamic_activate.upgrade() {
                if page.imp().is_mobile.get() {
                    page.set_drill_down_level(MailDrillDownLevel::Messages);
                }
            }
        });

        let click_for_dynamic_folder = gtk::GestureClick::new();
        let page_for_dynamic_click = self.downgrade();
        click_for_dynamic_folder.connect_released(move |_, _, _, _| {
            if let Some(page) = page_for_dynamic_click.upgrade() {
                if page.imp().is_mobile.get() {
                    page.set_drill_down_level(MailDrillDownLevel::Messages);
                }
            }
        });
        dynamic_folder_view.add_controller(click_for_dynamic_folder);

        self.imp()
            .dynamic_folder_store
            .replace(Some(dynamic_folder_store));
        self.imp()
            .dynamic_folder_selection
            .replace(Some(dynamic_folder_selection.clone()));
        self.imp()
            .dynamic_folder_children
            .replace(Some(Rc::clone(&dynamic_folder_children)));
        self.imp()
            .dynamic_folder_index
            .replace(Some(Rc::clone(&dynamic_folder_index)));

        let page_for_dynamic_selection = self.downgrade();
        dynamic_folder_selection.connect_selected_item_notify(move |selection| {
            let Some(page) = page_for_dynamic_selection.upgrade() else {
                return;
            };
            if page.imp().updating_folder_rows.get() || page.imp().saved_search_applying.get() {
                return;
            }
            page.set_saved_search_target_valid(true);
            let Some(row) = selection.selected_item().and_downcast::<gtk::TreeListRow>() else {
                return;
            };
            let Some(folder) = row.item().and_downcast::<FolderObject>() else {
                return;
            };
            let is_account_root = row.depth() == 0;
            if !folder.selectable() || is_account_root {
                return;
            }
            let Some(source_uid) = folder.source_uid() else {
                return;
            };
            let folder_name = folder
                .folder_name()
                .filter(|folder_name| !folder_name.trim().is_empty());
            let folder_selection = FolderSelection {
                folder_id: folder.id(),
                source_uid: Some(source_uid.clone()),
                folder_name: folder_name.clone(),
            };
            if let Some(current) = page.imp().folder_selection.borrow().as_ref() {
                current.replace(folder_selection.clone());
            }
            page.update_drawer_header_with_selection(
                &folder_selection,
                Some(folder.total_count() as usize),
            );
            if let Some(folder_list) = page.imp().folder_list.borrow().as_ref() {
                folder_list.unselect_all();
            }
            if let Some(unified_list) = page.imp().unified_folder_list.borrow().as_ref() {
                unified_list.unselect_all();
            }
            if let Some(search_list) = page.imp().search_list.borrow().as_ref() {
                search_list.unselect_all();
            }
            if let Some(search_entry) = page.imp().search_entry.borrow().as_ref() {
                search_entry.set_text("");
            }
            if let Some(filter_state) = page.imp().message_filter_state.borrow().as_ref() {
                filter_state.set(MessageFilter::All);
            }
            if let Some(query) = page.imp().search_query.borrow().as_ref() {
                query.replace(MessageSearchQuery::default());
            }
            if let Some(quick_filter) = page.imp().quick_filter.borrow().as_ref() {
                quick_filter.set_selected(0);
            }
            if let Some(filter) = page.imp().message_filter.borrow().as_ref() {
                filter.changed(gtk::FilterChange::Different);
            }
            if let Some(filter) = page.imp().thread_filter.borrow().as_ref() {
                filter.changed(gtk::FilterChange::Different);
            }
            if let Some(root) = page.root().and_downcast::<crate::window::EvolutionWindow>() {
                root.update_folder_sort_order_action_for_current_view();
                root.update_folder_properties_action_for_current_view();
                root.update_folder_subscriptions_action_for_current_view();
            }
            page.start_mail_load(
                MailLoadRequest {
                    source_uid: Some(source_uid),
                    folder_name,
                    offset: 0,
                    max_messages_per_folder: configured_mail_page_limit(),
                    graph_cursors: HashMap::new(),
                },
                true,
            );
            if page.imp().is_mobile.get() {
                page.set_drill_down_level(MailDrillDownLevel::Messages);
            }
        });

        let search_header = gtk::Label::builder()
            .label(&crate::i18n::gettext("Search Folders"))
            .css_classes(vec!["sidebar-section-header"])
            .halign(gtk::Align::Start)
            .margin_start(8)
            .margin_top(4)
            .margin_bottom(2)
            .build();

        let search_list = gtk::ListBox::new();
        search_list.set_selection_mode(gtk::SelectionMode::Single);
        search_list.add_css_class("navigation-sidebar");
        search_list.set_margin_start(2);
        Self::populate_search_folders(&search_list);

        let local_folder_toolbar = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .margin_start(4)
            .margin_end(4)
            .margin_top(3)
            .margin_bottom(1)
            .build();
        let local_folder_header = gtk::Label::builder()
            .label(&gettext("On This Computer"))
            .css_classes(vec!["sidebar-section-header"])
            .halign(gtk::Align::Start)
            .hexpand(true)
            .ellipsize(pango::EllipsizeMode::End)
            .build();
        let new_local_folder_button = gtk::Button::builder()
            .icon_name("folder-new-symbolic")
            .tooltip_text(&gettext("Create local folder"))
            .css_classes(vec!["flat", "circular"])
            .valign(gtk::Align::Center)
            .build();
        local_folder_toolbar.append(&local_folder_header);
        local_folder_toolbar.append(&new_local_folder_button);

        let unified_folder_toolbar = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .margin_start(4)
            .margin_end(4)
            .margin_top(3)
            .margin_bottom(1)
            .build();
        let unified_folder_header = gtk::Label::builder()
            .label(&gettext("Unified Folders"))
            .css_classes(vec!["sidebar-section-header"])
            .halign(gtk::Align::Start)
            .hexpand(true)
            .ellipsize(pango::EllipsizeMode::End)
            .build();
        unified_folder_toolbar.append(&unified_folder_header);

        let unified_folder_list = gtk::ListBox::new();
        unified_folder_list.set_selection_mode(gtk::SelectionMode::Single);
        unified_folder_list.add_css_class("navigation-sidebar");
        unified_folder_list.set_margin_start(2);

        unified_folder_list.append(&Self::create_folder_row(
            "unified_inbox",
            "mail-folder-inbox-symbolic",
            &gettext("All Inboxes"),
            "",
        ));
        unified_folder_list.append(&Self::create_folder_row(
            "unified_unread",
            "mail-unread-symbolic",
            &gettext("All Unread"),
            "",
        ));
        unified_folder_list.append(&Self::create_folder_row(
            "unified_flagged",
            "starred-symbolic",
            &gettext("All Flagged"),
            "",
        ));
        unified_folder_list.append(&Self::create_folder_row(
            "unified_sent",
            "mail-send-symbolic",
            &gettext("All Sent"),
            "",
        ));

        let unified_enabled = AppSettings::try_new()
            .map(|s| s.mail_enable_unified_inbox())
            .unwrap_or(true);

        let unified_folder_section = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .visible(unified_enabled)
            .build();
        unified_folder_section.append(&unified_folder_toolbar);
        unified_folder_section.append(&unified_folder_list);
        self.imp()
            .unified_folder_section
            .replace(Some(unified_folder_section.clone()));
        self.imp()
            .unified_folder_list
            .replace(Some(unified_folder_list.clone()));

        let folder_section = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .visible(true)
            .build();
        let page_for_new_local_folder = self.downgrade();
        new_local_folder_button.connect_clicked(move |_| {
            if let Some(page) = page_for_new_local_folder.upgrade() {
                page.present_local_folder_dialog(None);
            }
        });
        let local_folder_section = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .visible(false)
            .build();
        local_folder_section.append(&local_folder_toolbar);
        local_folder_section.append(&folder_list);
        self.imp()
            .local_folder_section
            .replace(Some(local_folder_section.clone()));
        folder_section.append(&unified_folder_section);
        folder_section.append(&local_folder_section);
        let search_section = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .visible(false)
            .build();
        search_section.append(&search_header);
        search_section.append(&search_list);

        folder_section.append(&dynamic_folder_view);
        folder_section.append(&search_section);

        let sidebar_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(0)
            .margin_start(0)
            .margin_end(0)
            .css_classes(vec!["mail-sidebar"])
            .build();

        let source_state = gtk::Label::builder()
            .label(&gettext("Loading accounts…"))
            .css_classes(vec!["dim-label"])
            .visible(false)
            .halign(gtk::Align::Start)
            .wrap(false)
            .ellipsize(gtk::pango::EllipsizeMode::End)
            .margin_start(12)
            .margin_end(12)
            .margin_bottom(4)
            .build();
        sidebar_box.append(&source_view);
        sidebar_box.append(&folder_section);

        let source_status_area = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["mail-pane-status"])
            .build();
        source_status_area.append(&source_state);
        source_status_area.set_visible(false);
        let source_status_area_for_visibility = source_status_area.clone();
        source_state.connect_visible_notify(move |state| {
            let statusbar_enabled = AppSettings::try_new()
                .map(|settings| settings.mail_show_statusbar())
                .unwrap_or(true);
            source_status_area_for_visibility.set_visible(statusbar_enabled && state.is_visible());
        });
        self.imp()
            .source_status_area
            .replace(Some(source_status_area.clone()));

        let drawer_header = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(8)
            .margin_start(4)
            .margin_end(4)
            .visible(false)
            .css_classes(vec!["sidebar-drawer-header"])
            .build();
        let drawer_icon = gtk::Image::from_icon_name("mail-inbox-symbolic");
        let drawer_title = gtk::Label::builder()
            .label(&crate::i18n::gettext("Inbox"))
            .halign(gtk::Align::Start)
            .hexpand(true)
            .ellipsize(pango::EllipsizeMode::End)
            .build();
        let drawer_total = gtk::Label::builder()
            .label("")
            .halign(gtk::Align::End)
            .valign(gtk::Align::Center)
            .visible(false)
            .css_classes(vec!["sidebar-drawer-total", "sidebar-drawer-unread-badge"])
            .build();
        drawer_header.append(&drawer_icon);
        drawer_header.append(&drawer_title);
        drawer_header.append(&drawer_total);
        drawer_header.set_visible(false);
        self.imp().drawer_header_box.replace(Some(drawer_header.clone()));
        self.imp().drawer_header_title.replace(Some(drawer_title));
        self.imp().drawer_header_icon.replace(Some(drawer_icon));
        self.imp().drawer_header_total.replace(Some(drawer_total));

        let sidebar_scroll = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Never)
            .vscrollbar_policy(gtk::PolicyType::Automatic)
            .propagate_natural_width(false)
            .min_content_height(40)
            .child(&sidebar_box)
            .build();
        let sidebar_content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .css_classes(vec!["evolution-sidebar-drawer"])
            .build();
        sidebar_scroll.set_vexpand(true);
        sidebar_content.append(&drawer_header);
        sidebar_content.append(&sidebar_scroll);
        sidebar_content.append(&source_status_area);

        sidebar_content.append(&crate::views::build_sidebar_module_switcher(
            "mail",
            &sidebar_content,
        ));

        (
            sidebar_content,
            source_store,
            source_state,
            folder_section,
            folder_list,
            search_list,
        )
    }

    fn create_folder_row(
        folder_id: &str,
        icon_name: &str,
        label_text: &str,
        badge_text: &str,
    ) -> gtk::ListBoxRow {
        Self::create_folder_row_with_backend(
            folder_id, icon_name, label_text, badge_text, None, None, false,
        )
    }

    fn create_search_folder_row(
        folder_id: &str,
        icon_name: &str,
        label_text: &str,
        badge_text: &str,
    ) -> gtk::ListBoxRow {
        Self::create_folder_row(folder_id, icon_name, label_text, badge_text)
    }

    fn populate_search_folders(search_list: &gtk::ListBox) {
        while let Some(row) = search_list.row_at_index(0) {
            search_list.remove(&row);
        }
        for folder in SearchFolderService::default_vfolders() {
            let Some(saved_search) = SavedSearch::with_metadata(
                folder.id(),
                folder.name(),
                folder.query_expression(),
                SavedSearchFieldMode::FreeForm,
                SavedSearchScope::AllAccounts,
                None,
                None,
                None,
            )
            .ok() else {
                tracing::warn!(id = %folder.id(), "Could not compile built-in saved search");
                continue;
            };
            let row = Self::create_search_folder_row(
                &folder.id(),
                &folder.icon_name(),
                &folder.name(),
                "",
            );
            unsafe {
                row.set_data("saved-search", saved_search);
            }
            search_list.append(&row);
        }
        for search in SearchFolderService::default().load_saved() {
            let row = Self::create_search_folder_row(
                &format!("saved-search:{}", search.id),
                "edit-find-symbolic",
                &search.name,
                "",
            );
            unsafe {
                row.set_data("saved-search", search.clone());
            }
            let edit_button = gtk::Button::builder()
                .icon_name("document-edit-symbolic")
                .tooltip_text(&gettext("Edit saved search folder"))
                .css_classes(vec!["flat", "circular"])
                .valign(gtk::Align::Center)
                .build();
            let delete_button = gtk::Button::builder()
                .icon_name("user-trash-symbolic")
                .tooltip_text(&gettext("Delete saved search folder"))
                .css_classes(vec!["flat", "circular"])
                .valign(gtk::Align::Center)
                .build();
            if let Some(box_container) = row.child().and_downcast::<gtk::Box>() {
                box_container.append(&edit_button);
                box_container.append(&delete_button);
            }
            let search_for_edit = search.clone();
            let search_list_for_edit = search_list.clone();
            edit_button.connect_clicked(move |button| {
                let Some(root) = button.root().and_downcast::<gtk::Window>() else {
                    tracing::warn!("Could not find a parent window for saved search editing");
                    return;
                };
                let dialog = crate::dialogs::SearchFolderDialog::new_for_edit(&search_for_edit);
                dialog.set_transient_for(Some(&root));
                let search_list_for_close = search_list_for_edit.clone();
                dialog.connect_close_request(move |_| {
                    Self::populate_search_folders(&search_list_for_close);
                    glib::Propagation::Proceed
                });
                dialog.present();
            });
            let row_for_delete = row.downgrade();
            let search_list_for_delete = search_list.clone();
            let search_id = search.id.clone();
            delete_button.connect_clicked(move |button| {
                let row_for_action = row_for_delete.clone();
                let search_list_for_action = search_list_for_delete.clone();
                let search_id_for_action = search_id.clone();
                let heading = gettext("Delete saved search folder?");
                let body = gettext("The local search definition will be permanently removed.");
                let del_lbl = gettext("Delete");
                crate::dialogs::run_destructive_action(
                    button,
                    &heading,
                    &body,
                    &del_lbl,
                    move || match SearchFolderService::default().delete_saved(&search_id_for_action)
                    {
                        Ok(true) => {
                            if let Some(row) = row_for_action.upgrade() {
                                search_list_for_action.remove(&row);
                            }
                        }
                        Ok(false) => {}
                        Err(error) => tracing::warn!(%error, "Could not delete saved search"),
                    },
                );
            });
            search_list.append(&row);
        }
    }

    fn create_folder_row_with_backend(
        folder_id: &str,
        icon_name: &str,
        label_text: &str,
        badge_text: &str,
        source_uid: Option<&str>,
        folder_name: Option<&str>,
        dynamic: bool,
    ) -> gtk::ListBoxRow {
        let hbox = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(6)
            .margin_start(6)
            .margin_end(6)
            .css_classes(vec!["mail-sidebar-row"])
            .build();

        let icon = gtk::Image::from_icon_name(icon_name);
        icon.add_css_class("dim-label");

        let label = gtk::Label::builder()
            .label(label_text)
            .halign(gtk::Align::Start)
            .hexpand(true)
            .ellipsize(pango::EllipsizeMode::End)
            .build();

        hbox.append(&icon);
        hbox.append(&label);

        let badge = gtk::Label::builder()
            .label(badge_text)
            .css_classes(vec!["badge", "numeric"])
            .halign(gtk::Align::End)
            .visible(!badge_text.is_empty())
            .build();
        hbox.append(&badge);

        let row = gtk::ListBoxRow::builder().child(&hbox).build();
        unsafe {
            row.set_data("folder-id", folder_id.to_string());
            row.set_data("folder-badge", badge);
            row.set_data(
                "folder-row-data",
                FolderRowData {
                    folder_id: folder_id.to_string(),
                    source_uid: source_uid.map(str::to_string),
                    folder_name: folder_name.map(str::to_string),
                },
            );
            row.set_data("folder-dynamic", dynamic);
        }
        row
    }

    fn update_folder_counts(folder_list: &gtk::ListBox, counts: &HashMap<String, (u32, u32)>) {
        for index in 0..folder_list.observe_children().n_items() {
            let Some(row) = folder_list
                .row_at_index(index as i32)
                .and_downcast::<gtk::ListBoxRow>()
            else {
                continue;
            };
            let Some(folder_id) = Self::folder_id(&row) else {
                continue;
            };
            let key = if folder_id == "spam" {
                "junk"
            } else {
                folder_id.as_str()
            };
            let (unread, _total) = if folder_id == "all" {
                counts
                    .values()
                    .fold((0_u32, 0_u32), |(unread, total), value| {
                        (
                            unread.saturating_add(value.0),
                            total.saturating_add(value.1),
                        )
                    })
            } else if folder_id.starts_with("custom:") {
                counts
                    .iter()
                    .filter(|(candidate, _)| {
                        let candidate = candidate.as_str();
                        candidate == folder_id
                            || candidate
                                .strip_prefix(&folder_id)
                                .is_some_and(|rest| rest.starts_with('/'))
                    })
                    .fold((0_u32, 0_u32), |(unread, total), (_, value)| {
                        (
                            unread.saturating_add(value.0),
                            total.saturating_add(value.1),
                        )
                    })
            } else {
                counts.get(key).copied().unwrap_or((0, 0))
            };
            let Some(badge) = (unsafe {
                row.data::<gtk::Label>("folder-badge")
                    .map(|pointer| pointer.as_ref())
            }) else {
                continue;
            };
            badge.set_label(&unread.to_string());
            badge.set_visible(unread > 0);
        }
    }

    fn rebuild_local_folder_rows(
        &self,
        folder_list: &gtk::ListBox,
        counts: &HashMap<String, (u32, u32)>,
        definitions: &HashSet<String>,
    ) {
        let active_selection = self.active_folder_selection();
        let was_updating = self.imp().updating_folder_rows.replace(true);
        let mut stale_rows = Vec::new();
        let mut builtin_rows = HashMap::<String, gtk::ListBoxRow>::new();
        for index in 0..folder_list.observe_children().n_items() {
            let Some(row) = folder_list
                .row_at_index(index as i32)
                .and_downcast::<gtk::ListBoxRow>()
            else {
                continue;
            };
            let is_local_dynamic = unsafe {
                row.data::<bool>("folder-local-dynamic")
                    .map(|value| *value.as_ref())
                    .unwrap_or(false)
            };
            if is_local_dynamic {
                stale_rows.push(row);
            } else if let Some(folder_id) = Self::folder_id(&row)
                && LOCAL_SORTABLE_BUILTIN_FOLDER_IDS.contains(&folder_id.as_str())
            {
                builtin_rows.insert(folder_id, row);
            }
        }
        for row in stale_rows {
            folder_list.remove(&row);
        }
        for row in builtin_rows.values() {
            folder_list.remove(row);
        }

        let mut local_folders = HashSet::new();
        for folder_id in counts.keys().chain(definitions.iter()) {
            if folder_id.starts_with("custom:") {
                Self::add_local_folder_tree_ids(&mut local_folders, folder_id);
            }
        }
        let sort_order = self.folder_sort_order();
        let ordered_folders = ordered_local_sidebar_folder_ids(&local_folders, &sort_order);

        let collapsed = self.imp().local_folder_collapsed.borrow().clone();
        for folder_id in ordered_folders {
            if let Some(row) = builtin_rows.remove(&folder_id) {
                folder_list.append(&row);
                continue;
            }
            if Self::local_folder_has_collapsed_parent(&folder_id, &collapsed) {
                continue;
            }
            let has_children = local_folders.iter().any(|candidate| {
                candidate != &folder_id
                    && candidate
                        .strip_prefix(&format!("{folder_id}/"))
                        .is_some_and(|rest| !rest.is_empty())
            });
            let row = Self::create_folder_row_with_backend(
                &folder_id,
                "folder-symbolic",
                &Self::local_folder_display_label(&folder_id),
                "",
                None,
                None,
                true,
            );
            if let Some(container) = row.child().and_downcast::<gtk::Box>() {
                container
                    .set_margin_start(compact_folder_indent(Self::local_folder_depth(&folder_id)));
            }
            unsafe {
                row.set_data("folder-local-dynamic", true);
            }
            self.add_local_folder_expander(&row, &folder_id, has_children);
            self.add_local_folder_actions(&row, &folder_id);
            self.install_local_folder_drag_and_drop(&row, &folder_id);
            folder_list.append(&row);
        }
        Self::update_folder_counts(folder_list, counts);
        self.imp().updating_folder_rows.set(was_updating);
        if !was_updating {
            // Built-in rows participate in top-level custom ordering, so the
            // ListBox replaces them during a rebuild. Restore the existing
            // reader selection without routing it through the load callback.
            self.select_folder_row(&active_selection);
        }
    }

    fn add_local_folder_tree_ids(folder_ids: &mut HashSet<String>, folder_id: &str) {
        let Some(path) = folder_id.strip_prefix("custom:") else {
            return;
        };
        let mut prefix = String::new();
        for segment in path.split('/').filter(|segment| !segment.is_empty()) {
            if !prefix.is_empty() {
                prefix.push('/');
            }
            prefix.push_str(segment);
            folder_ids.insert(format!("custom:{prefix}"));
        }
    }

    fn local_folder_depth(folder_id: &str) -> usize {
        folder_id
            .strip_prefix("custom:")
            .map(|path| {
                path.split('/')
                    .filter(|segment| !segment.is_empty())
                    .count()
            })
            .unwrap_or(1)
            .saturating_sub(1)
    }

    fn local_folder_display_label(folder_id: &str) -> String {
        folder_id
            .strip_prefix("custom:")
            .unwrap_or(folder_id)
            .rsplit('/')
            .next()
            .filter(|segment| !segment.is_empty())
            .unwrap_or(folder_id)
            .to_string()
    }

    fn local_folder_sort_label(folder_id: &str) -> String {
        match folder_id {
            "inbox" => crate::i18n::gettext("Inbox"),
            "sent" => crate::i18n::gettext("Sent"),
            "drafts" => crate::i18n::gettext("Drafts"),
            "trash" => crate::i18n::gettext("Trash"),
            "archive" => crate::i18n::gettext("Archive"),
            "spam" => crate::i18n::gettext("Junk"),
            _ => Self::local_folder_display_label(folder_id),
        }
    }

    fn local_folder_has_collapsed_parent(folder_id: &str, collapsed: &HashSet<String>) -> bool {
        let Some(path) = folder_id.strip_prefix("custom:") else {
            return false;
        };
        let segments = path.split('/').filter(|segment| !segment.is_empty());
        let mut prefix = String::new();
        for (index, segment) in segments.enumerate() {
            if index + 1 == path.split('/').filter(|value| !value.is_empty()).count() {
                break;
            }
            if !prefix.is_empty() {
                prefix.push('/');
            }
            prefix.push_str(segment);
            if collapsed.contains(&format!("custom:{prefix}")) {
                return true;
            }
        }
        false
    }

    fn add_local_folder_expander(
        &self,
        row: &gtk::ListBoxRow,
        folder_id: &str,
        has_children: bool,
    ) {
        if !has_children {
            return;
        }
        let collapsed = self
            .imp()
            .local_folder_collapsed
            .borrow()
            .contains(folder_id);
        let button = gtk::Button::builder()
            .icon_name(if collapsed {
                "pan-end-symbolic"
            } else {
                "pan-down-symbolic"
            })
            .tooltip_text(if collapsed {
                "Unterordner einblenden"
            } else {
                "Unterordner ausblenden"
            })
            .css_classes(vec!["flat", "circular"])
            .valign(gtk::Align::Center)
            .build();
        if let Some(container) = row.child().and_downcast::<gtk::Box>() {
            container.prepend(&button);
        }
        let folder_id = folder_id.to_string();
        let page = self.downgrade();
        button.connect_clicked(move |_| {
            let Some(page) = page.upgrade() else {
                return;
            };
            let mut collapsed = page.imp().local_folder_collapsed.borrow_mut();
            if !collapsed.insert(folder_id.clone()) {
                collapsed.remove(&folder_id);
            }
            drop(collapsed);
            page.refresh_mail();
        });
    }

    fn add_local_folder_actions(&self, row: &gtk::ListBoxRow, folder_id: &str) {
        let Some(container) = row.child().and_downcast::<gtk::Box>() else {
            return;
        };

        let rename_button = gtk::Button::builder()
            .icon_name("document-edit-symbolic")
            .tooltip_text(&gettext("Rename local folder"))
            .css_classes(vec!["flat", "circular"])
            .valign(gtk::Align::Center)
            .build();
        let delete_button = gtk::Button::builder()
            .icon_name("user-trash-symbolic")
            .tooltip_text(&gettext("Delete empty local folder"))
            .css_classes(vec!["flat", "circular"])
            .valign(gtk::Align::Center)
            .build();
        container.append(&rename_button);
        container.append(&delete_button);

        let folder_id_for_rename = folder_id.to_string();
        let page_for_rename = self.downgrade();
        rename_button.connect_clicked(move |_| {
            if let Some(page) = page_for_rename.upgrade() {
                page.present_local_folder_dialog(Some(&folder_id_for_rename));
            }
        });

        let folder_id_for_delete = folder_id.to_string();
        let page_for_delete = self.downgrade();
        delete_button.connect_clicked(move |button| {
            let folder_id = folder_id_for_delete.clone();
            let page = page_for_delete.clone();
            let heading = gettext("Delete local folder?");
            let body = gettext("Only empty app-owned folders can be deleted. Imported mail files remain unchanged.");
            let del_lbl = gettext("Delete");
            crate::dialogs::run_destructive_action(
                button,
                &heading,
                &body,
                &del_lbl,
                move || {
                    let result = crate::services::MailStoreService::new()
                        .delete_local_folder(&folder_id);
                    if let Some(page) = page.upgrade() {
                        match result {
                            Ok(()) => page.refresh_mail(),
                            Err(error) => page.show_toast(&format!(
                                "{}: {error}",
                                gettext("Local folder could not be deleted")
                            )),
                        }
                    }
                },
            );
        });
    }
    fn localize_folder_name(name: &str) -> String {
        let clean = name.trim();
        match clean.to_ascii_lowercase().as_str() {
            "inbox" | "posteingang" => crate::i18n::gettext("Inbox"),
            "drafts" | "entwürfe" | "entwuerfe" => crate::i18n::gettext("Drafts"),
            "sent" | "sent items" | "gesendet" => crate::i18n::gettext("Sent"),
            "trash" | "mülleimer" | "papierkorb" | "deleted items" => crate::i18n::gettext("Trash"),
            "junk" | "junk email" | "spam" => crate::i18n::gettext("Junk"),
            "archive" | "archiv" => crate::i18n::gettext("Archive"),
            "outbox" | "postausgang" => crate::i18n::gettext("Outbox"),
            _ => clean.to_string(),
        }
    }

    fn localize_source_name(name: &str) -> String {
        let clean = name.trim();
        let normalized = clean.to_ascii_lowercase();
        if normalized.contains("eds")
            || normalized.contains("camel")
            || normalized.contains("gnome online")
            || normalized == "goa"
        {
            return crate::i18n::gettext("Mail Account");
        }
        match normalized.as_str() {
            "on this computer" | "local" => crate::i18n::gettext("On This Computer"),
            "search folders" | "vfolder" => crate::i18n::gettext("Search Folders"),
            "news and blogs" | "rss" => crate::i18n::gettext("News & Blogs"),
            _ => clean.to_string(),
        }
    }

    fn rebuild_camel_folder_rows(
        &self,
        folder_list: &gtk::ListBox,
        folders: &[camel_mail_service::CamelFolderSummary],
    ) {
        self.rebuild_camel_folder_rows_with_force(folder_list, folders, false);
    }

    fn force_rebuild_camel_folder_rows(
        &self,
        folder_list: &gtk::ListBox,
        folders: &[camel_mail_service::CamelFolderSummary],
    ) {
        self.rebuild_camel_folder_rows_with_force(folder_list, folders, true);
    }

    fn rebuild_camel_folder_rows_with_force(
        &self,
        folder_list: &gtk::ListBox,
        folders: &[camel_mail_service::CamelFolderSummary],
        force: bool,
    ) {
        let started = Instant::now();
        tracing::debug!(
            folder_count = folders.len(),
            force,
            "Rebuilding EDS/Camel folder rows"
        );
        let was_updating = self.imp().updating_folder_rows.replace(true);
        let mut dynamic_rows = Vec::new();
        for index in 0..folder_list.observe_children().n_items() {
            let Some(row) = folder_list
                .row_at_index(index as i32)
                .and_downcast::<gtk::ListBoxRow>()
            else {
                continue;
            };
            let is_dynamic = unsafe {
                row.data::<bool>("folder-dynamic")
                    .map(|value| *value.as_ref())
                    .unwrap_or(false)
            };
            if is_dynamic {
                dynamic_rows.push(row);
            }
        }
        for row in dynamic_rows {
            folder_list.remove(&row);
        }

        let Some(root_store) = self.imp().dynamic_folder_store.borrow().as_ref().cloned() else {
            self.imp().updating_folder_rows.set(was_updating);
            return;
        };
        let Some(children) = self
            .imp()
            .dynamic_folder_children
            .borrow()
            .as_ref()
            .cloned()
        else {
            self.imp().updating_folder_rows.set(was_updating);
            return;
        };
        let Some(index) = self.imp().dynamic_folder_index.borrow().as_ref().cloned() else {
            self.imp().updating_folder_rows.set(was_updating);
            return;
        };

        let has_children = !children.borrow().is_empty();
        let has_all_folders = !folders.is_empty()
            && folders.iter().all(|f| {
                let key = Self::dynamic_folder_key(&f.source_uid, &f.folder_name);
                index.borrow().contains_key(&key)
            });
        if !force && root_store.n_items() > 0 && has_children && has_all_folders {
            self.update_camel_folder_counts(folder_list, folders, None);
            self.imp().updating_folder_rows.set(was_updating);
            return;
        }

        // Save expanded folder IDs before modifying the store
        let mut expanded_ids = self.imp().dynamic_folder_expanded.borrow().clone();
        if let Some(dynamic_selection) = self.imp().dynamic_folder_selection.borrow().as_ref() {
            if dynamic_selection.n_items() > 0 {
                for index in 0..dynamic_selection.n_items() {
                    if let Some(row) = dynamic_selection
                        .item(index)
                        .and_downcast::<gtk::TreeListRow>()
                    {
                        if let Some(folder) = row.item().and_downcast::<FolderObject>() {
                            if row.is_expanded() {
                                expanded_ids.insert(folder.id());
                            } else {
                                expanded_ids.remove(&folder.id());
                            }
                        }
                    }
                }
                *self.imp().dynamic_folder_expanded.borrow_mut() = expanded_ids.clone();
                self.persist_dynamic_folder_expanded(&expanded_ids);
            }
        }

        let mut seen_nodes = HashSet::new();
        let mut nodes = Vec::<DynamicFolderNode>::new();
        for folder in folders {
            if folder.source_uid == "local"
                || folder.source_display_name.to_ascii_lowercase().contains("computer")
                || folder.source_display_name.to_ascii_lowercase() == "local"
                || folder.folder_name.starts_with('.')
                || folder.folder_name.contains("/.")
                || folder.display_name.starts_with('.')
            {
                continue;
            }
            let canonical_src = folder.source_uid.strip_prefix("eds:").unwrap_or(&folder.source_uid);
            let key = Self::dynamic_folder_key(canonical_src, &folder.folder_name);
            if !seen_nodes.insert(key) {
                continue;
            }
            let parent_name = Self::parent_folder_name(&folder.folder_name);
            nodes.push(DynamicFolderNode {
                source_uid: canonical_src.to_string(),
                source_display_name: folder.source_display_name.clone(),
                folder_name: folder.folder_name.clone(),
                display_name: folder.display_name.clone(),
                icon_name: Self::folder_icon_name(&folder.folder_id).to_string(),
                unread_count: folder.unread_count,
                total_count: folder.total_count,
                selectable: folder.is_selectable,
                parent_name,
            });
        }

        let mut known_nodes = nodes
            .iter()
            .map(|node| Self::dynamic_folder_key(&node.source_uid, &node.folder_name))
            .collect::<HashSet<_>>();
        let mut synthetic_nodes = Vec::new();
        for node in &nodes {
            let mut parent_name = node.parent_name.clone();
            while let Some(parent) = parent_name {
                let key = Self::dynamic_folder_key(&node.source_uid, &parent);
                if known_nodes.insert(key) {
                    synthetic_nodes.push(DynamicFolderNode {
                        source_uid: node.source_uid.clone(),
                        source_display_name: node.source_display_name.clone(),
                        folder_name: parent.clone(),
                        display_name: parent
                            .rsplit('/')
                            .next()
                            .filter(|name| !name.is_empty())
                            .unwrap_or(parent.as_str())
                            .to_string(),
                        icon_name: "folder-symbolic".to_string(),
                        unread_count: 0,
                        total_count: 0,
                        selectable: false,
                        parent_name: Self::parent_folder_name(&parent),
                    });
                }
                parent_name = Self::parent_folder_name(&parent);
            }
        }
        nodes.extend(synthetic_nodes);
        let sort_order = self.folder_sort_order();
        nodes.sort_by(|left, right| {
            left.source_display_name
                .cmp(&right.source_display_name)
                .then_with(|| left.source_uid.cmp(&right.source_uid))
                .then_with(|| left.parent_name.cmp(&right.parent_name))
                .then_with(|| {
                    compare_folder_siblings(
                        &Self::dynamic_folder_key(&left.source_uid, &left.folder_name),
                        &left.display_name,
                        &Self::dynamic_folder_key(&right.source_uid, &right.folder_name),
                        &right.display_name,
                        &sort_order,
                    )
                })
        });

        let mut source_roots = HashMap::<String, FolderObject>::new();
        let mut source_counts = HashMap::<String, (u32, u32)>::new();
        for folder in folders {
            if folder.source_uid == "local"
                || folder.source_display_name.to_ascii_lowercase().contains("computer")
                || folder.source_display_name.to_ascii_lowercase() == "local"
            {
                continue;
            }
            let canonical_src = Self::canonical_account_uid(&folder.source_uid);
            let source_root_id = Self::dynamic_folder_key(canonical_src, "");
            source_roots
                .entry(canonical_src.to_string())
                .or_insert_with(|| {
                    let source_name = Self::localize_source_name(&folder.source_display_name);
                    FolderObject::new_backend(
                        &source_root_id,
                        if source_name.is_empty() {
                            "Mailkonto"
                        } else {
                            &source_name
                        },
                        "",
                        0,
                        0,
                        canonical_src,
                        "",
                        None,
                        true,
                    )
                });
            let counts = source_counts.entry(canonical_src.to_string()).or_default();
            counts.0 = counts.0.saturating_add(folder.unread_count);
        }

        // Ensure all configured account profiles are represented in source_roots,
        // so newly added or synchronizing accounts always appear in the sidebar
        for profile in AccountConfigStore::default().load() {
            if !profile.enabled {
                continue;
            }
            let eds_uid =
                crate::services::account_config_service::eds_source_uid_for_email(&profile.email);
            let profile_canonical = Self::canonical_account_uid(&profile.id).to_string();
            let eds_canonical = Self::canonical_account_uid(&eds_uid).to_string();
            let is_present = source_roots.contains_key(&profile_canonical)
                || source_roots.contains_key(&eds_canonical)
                || source_roots.contains_key(&profile.id)
                || source_roots.contains_key(&eds_uid)
                || source_roots.values().any(|r| {
                    let r_uid = r.source_uid().unwrap_or_default();
                    let r_canon = Self::canonical_account_uid(&r_uid);
                    r_canon == profile_canonical
                        || r_canon == eds_canonical
                        || (!profile.is_shared_mailbox
                            && (r.name().eq_ignore_ascii_case(&profile.display_name)
                                || r.name().eq_ignore_ascii_case(&profile.email)))
                });
            let root_icon = if profile.is_shared_mailbox {
                "system-users-symbolic"
            } else {
                ""
            };
            if !is_present {
                let source_root_id = Self::dynamic_folder_key(&profile_canonical, "");
                let display_name = if !profile.display_name.is_empty() {
                    profile.display_name.clone()
                } else {
                    profile.email.clone()
                };
                source_roots.insert(
                    profile_canonical.clone(),
                    FolderObject::new_backend(
                        &source_root_id,
                        &display_name,
                        root_icon,
                        0,
                        0,
                        &profile_canonical,
                        "",
                        None,
                        true,
                    ),
                );
            } else if profile.is_shared_mailbox {
                let target_key = if source_roots.contains_key(&profile_canonical) {
                    &profile_canonical
                } else {
                    &profile.id
                };
                if let Some(root) = source_roots.get(target_key) {
                    if root.icon_name().is_empty() {
                        let source_root_id = Self::dynamic_folder_key(&profile_canonical, "");
                        let display_name = if !profile.display_name.is_empty() {
                            profile.display_name.clone()
                        } else {
                            profile.email.clone()
                        };
                        source_roots.insert(
                            profile_canonical.clone(),
                            FolderObject::new_backend(
                                &source_root_id,
                                &display_name,
                                "system-users-symbolic",
                                0,
                                0,
                                &profile_canonical,
                                "",
                                None,
                                true,
                            ),
                        );
                    }
                }
            }

            if profile.is_shared_mailbox
                && !nodes.iter().any(|n| {
                    let n_canon = Self::canonical_account_uid(&n.source_uid);
                    n_canon == profile_canonical || n_canon == profile.id
                })
            {
                let display_name = if !profile.display_name.is_empty() {
                    profile.display_name.clone()
                } else {
                    profile.email.clone()
                };
                let default_folders = [
                    ("Posteingang", "Posteingang", "mail-inbox-symbolic"),
                    ("Gesendete Elemente", "Gesendete Elemente", "mail-send-symbolic"),
                    ("Entwürfe", "Entwürfe", "mail-drafts-symbolic"),
                    ("Gelöschte Elemente", "Gelöschte Elemente", "user-trash-symbolic"),
                    ("Junk-E-Mail", "Junk-E-Mail", "mail-spam-symbolic"),
                ];
                for (fname, dname, icon) in default_folders {
                    let key = Self::dynamic_folder_key(&profile_canonical, fname);
                    if seen_nodes.insert(key) {
                        nodes.push(DynamicFolderNode {
                            source_uid: profile_canonical.clone(),
                            source_display_name: display_name.clone(),
                            folder_name: fname.to_string(),
                            display_name: dname.to_string(),
                            icon_name: icon.to_string(),
                            unread_count: 0,
                            total_count: 0,
                            selectable: true,
                            parent_name: None,
                        });
                    }
                }
            }
        }

        // Ensure all discovered/cached EDS mail sources (such as GNOME Online Accounts / Google accounts)
        // are represented in source_roots, so they appear immediately in the sidebar on startup.
        let eds_cache = crate::services::eds_source_cache_service::EdsSourceCache::new();
        for eds_source in eds_cache
            .load_with_status(crate::services::eds_service::EdsSourceKind::Mail)
            .sources
        {
            if !eds_source.enabled {
                continue;
            }
            if eds_source.uid == "vfolder"
                || eds_source.uid == "rss"
                || eds_source.uid == "local"
                || eds_source.display_name.to_ascii_lowercase().contains("computer")
            {
                continue;
            }
            let eds_canonical = Self::canonical_account_uid(&eds_source.uid);
            let is_present = source_roots.contains_key(eds_canonical)
                || source_roots.contains_key(&eds_source.uid)
                || source_roots.values().any(|r| {
                    let r_uid = r.source_uid().unwrap_or_default();
                    let r_canon = Self::canonical_account_uid(&r_uid);
                    r_canon == eds_canonical
                        || r.name().eq_ignore_ascii_case(&eds_source.display_name)
                        || eds_source
                            .parent_name
                            .as_deref()
                            .is_some_and(|p| r.name().eq_ignore_ascii_case(p))
                });
            if !is_present {
                let source_root_id = Self::dynamic_folder_key(eds_canonical, "");
                let display_name = Self::localize_source_name(&eds_source.display_name);
                source_roots.insert(
                    eds_canonical.to_string(),
                    FolderObject::new_backend(
                        &source_root_id,
                        &display_name,
                        "",
                        0,
                        0,
                        eds_canonical,
                        "",
                        None,
                        true,
                    ),
                );
            }
        }

        if let Some(source_store) = self
            .imp()
            .source_selection
            .borrow()
            .as_ref()
            .and_then(|s| s.model())
            .and_downcast::<gio::ListStore>()
        {
            for i in 0..source_store.n_items() {
                if let Some(source_obj) = source_store.item(i).and_downcast::<EdsSourceObject>() {
                    if !source_obj.enabled() {
                        continue;
                    }
                    let s_uid = source_obj.uid();
                    let d_name = source_obj.display_name();
                    if s_uid == "vfolder"
                        || s_uid == "rss"
                        || s_uid == "local"
                        || d_name.to_ascii_lowercase().contains("computer")
                    {
                        continue;
                    }
                    let s_canonical = Self::canonical_account_uid(&s_uid);
                    let is_present = source_roots.contains_key(s_canonical)
                        || source_roots.contains_key(&s_uid)
                        || source_roots.values().any(|r| {
                            let r_uid = r.source_uid().unwrap_or_default();
                            let r_canon = Self::canonical_account_uid(&r_uid);
                            r_canon == s_canonical || r.name().eq_ignore_ascii_case(&d_name)
                        });
                    if !is_present {
                        let source_root_id = Self::dynamic_folder_key(s_canonical, "");
                        source_roots.insert(
                            s_canonical.to_string(),
                            FolderObject::new_backend(
                                &source_root_id,
                                &d_name,
                                "",
                                0,
                                0,
                                s_canonical,
                                "",
                                None,
                                true,
                            ),
                        );
                    }
                }
            }
        }

        // Ensure all accounts represented in source_roots have child folder nodes,
        // so that every account (including EWS, GNOME Online Accounts, offline stores)
        // gets its full folder hierarchy and expander arrow.
        for (source_uid, root_obj) in &source_roots {
            let canon = Self::canonical_account_uid(source_uid);
            let has_nodes = nodes.iter().any(|n| {
                let n_canon = Self::canonical_account_uid(&n.source_uid);
                n_canon == canon
            });
            if !has_nodes {
                let display_name = root_obj.name();
                let cached_folders = camel_mail_service::load_evolution_cached_folders(
                    canon,
                    &display_name,
                );
                for folder in cached_folders {
                    let key = Self::dynamic_folder_key(canon, &folder.folder_name);
                    if !seen_nodes.insert(key) {
                        continue;
                    }
                    let parent_name = Self::parent_folder_name(&folder.folder_name);
                    nodes.push(DynamicFolderNode {
                        source_uid: canon.to_string(),
                        source_display_name: folder.source_display_name.clone(),
                        folder_name: folder.folder_name.clone(),
                        display_name: folder.display_name.clone(),
                        icon_name: Self::folder_icon_name(&folder.folder_id).to_string(),
                        unread_count: folder.unread_count,
                        total_count: folder.total_count,
                        selectable: folder.is_selectable,
                        parent_name,
                    });
                    let counts = source_counts.entry(canon.to_string()).or_default();
                    counts.0 = counts.0.saturating_add(folder.unread_count);
                    counts.1 = counts.1.saturating_add(folder.total_count);
                }
            }
        }

        let sort_order = self.folder_sort_order();
        nodes.sort_by(|left, right| {
            left.source_display_name
                .cmp(&right.source_display_name)
                .then_with(|| left.source_uid.cmp(&right.source_uid))
                .then_with(|| left.parent_name.cmp(&right.parent_name))
                .then_with(|| {
                    compare_folder_siblings(
                        &Self::dynamic_folder_key(&left.source_uid, &left.folder_name),
                        &left.display_name,
                        &Self::dynamic_folder_key(&right.source_uid, &right.folder_name),
                        &right.display_name,
                        &sort_order,
                    )
                })
        });

        let mut roots = source_roots.values().cloned().collect::<Vec<_>>();
        if roots.is_empty() && root_store.n_items() == 0 {
            self.imp().updating_folder_rows.set(was_updating);
            return;
        }

        // Deduplicate roots by canonical account UID
        let mut unique_roots = Vec::new();
        let mut seen_root_uids = HashSet::new();
        for root in roots {
            let canon = Self::canonical_account_uid(&root.source_uid().unwrap_or_default()).to_string();
            if seen_root_uids.insert(canon) {
                unique_roots.push(root);
            }
        }
        let mut roots = unique_roots;

        let profiles = AccountConfigStore::default().load();
        let shared_uids: HashSet<String> = profiles
            .iter()
            .filter(|p| p.is_shared_mailbox)
            .flat_map(|p| {
                let eds_uid = crate::services::account_config_service::eds_source_uid_for_email(&p.email);
                let p_canon = Self::canonical_account_uid(&p.id).to_string();
                let e_canon = Self::canonical_account_uid(&eds_uid).to_string();
                vec![p.id.clone(), eds_uid, p_canon, e_canon]
            })
            .collect();

        roots.sort_by(|a, b| {
            let a_uid = a.source_uid().unwrap_or_default();
            let b_uid = b.source_uid().unwrap_or_default();
            let a_shared = a.icon_name() == "system-users-symbolic"
                || shared_uids.contains(&a_uid)
                || shared_uids.contains(Self::canonical_account_uid(&a_uid));
            let b_shared = b.icon_name() == "system-users-symbolic"
                || shared_uids.contains(&b_uid)
                || shared_uids.contains(Self::canonical_account_uid(&b_uid));
            a_shared.cmp(&b_shared).then_with(|| a.name().cmp(&b.name()))
        });
        for root in &roots {
            let root_uid = root.source_uid().unwrap_or_default();
            let root_canon = Self::canonical_account_uid(&root_uid);
            if let Some((unread, total)) = source_counts.get(root_canon)
            {
                root.set_counts(*unread, *total);
            }
        }
        let mut child_stores = HashMap::<String, gio::ListStore>::new();
        let mut folder_index = HashMap::<String, FolderObject>::new();
        let mut seen_folder_in_parent = HashSet::<(String, String)>::new();
        for root in &roots {
            folder_index.insert(root.id(), root.clone());
        }
        let nodes_count = nodes.len();
        for node in nodes {
            let id = Self::dynamic_folder_key(&node.source_uid, &node.folder_name);
            let parent_id = node
                .parent_name
                .as_deref()
                .map(|name| Self::dynamic_folder_key(&node.source_uid, name))
                .unwrap_or_else(|| Self::dynamic_folder_key(&node.source_uid, ""));

            // Deduplicate per parent list store
            if !seen_folder_in_parent.insert((parent_id.clone(), node.folder_name.clone())) {
                continue;
            }

            let localized_display = Self::localize_folder_name(&node.display_name);
            let label = localized_display;
            let folder = FolderObject::new_backend(
                &id,
                &label,
                &node.icon_name,
                node.unread_count,
                node.total_count,
                &node.source_uid,
                &node.folder_name,
                Some(parent_id.as_str()),
                node.selectable,
            );
            child_stores
                .entry(parent_id)
                .or_insert_with(|| gio::ListStore::new::<FolderObject>())
                .append(&folder);
            folder_index.insert(id, folder);
        }

        root_store.remove_all();
        children.replace(child_stores);
        index.replace(folder_index);
        let roots_count = roots.len();
        for root in &roots {
            root_store.append(root);
        }
        if let Some(dynamic_selection) = self.imp().dynamic_folder_selection.borrow().as_ref() {
            let mut index = 0;
            while index < dynamic_selection.n_items() {
                if let Some(row) = dynamic_selection
                    .item(index)
                    .and_downcast::<gtk::TreeListRow>()
                {
                    let should_expand = row
                        .item()
                        .and_downcast::<FolderObject>()
                        .map(|folder| {
                            let id = folder.id();
                            let trimmed = id.trim_end_matches('\0');
                            expanded_ids.contains(&id)
                                || (!trimmed.is_empty() && expanded_ids.contains(trimmed))
                                || expanded_ids.contains(&format!("{trimmed}\0"))
                        })
                        .unwrap_or(false);
                    if should_expand || row.depth() == 0 {
                        row.set_expanded(true);
                    }
                }
                index += 1;
            }
        }
        let mut current_sel = self.active_folder_selection();
        let mut auto_selected_inbox = false;
        if current_sel.source_uid.is_none() {
            if let Some(dynamic_selection) = self.imp().dynamic_folder_selection.borrow().as_ref() {
                for i in 0..dynamic_selection.n_items() {
                    if let Some(row) = dynamic_selection.item(i).and_downcast::<gtk::TreeListRow>() {
                        if let Some(folder) = row.item().and_downcast::<FolderObject>() {
                            if folder.selectable()
                                && (folder.name().eq_ignore_ascii_case("posteingang")
                                    || folder
                                        .folder_name()
                                        .as_deref()
                                        .unwrap_or_default()
                                        .eq_ignore_ascii_case("inbox"))
                            {
                                current_sel = FolderSelection {
                                    folder_id: folder.id(),
                                    source_uid: folder.source_uid(),
                                    folder_name: folder.folder_name().filter(|f| !f.trim().is_empty()),
                                };
                                if let Some(cell) = self.imp().folder_selection.borrow().as_ref() {
                                    cell.replace(current_sel.clone());
                                }
                                auto_selected_inbox = true;
                                break;
                            }
                        }
                    }
                }
            }
        }
        self.select_folder_row(&current_sel);
        if auto_selected_inbox {
            if let Some(filter) = self.imp().message_filter.borrow().as_ref() {
                filter.changed(gtk::FilterChange::Different);
            }
            if let Some(filter) = self.imp().thread_filter.borrow().as_ref() {
                filter.changed(gtk::FilterChange::Different);
            }
        }
        if let Some(section) = self.imp().folder_section.borrow().as_ref() {
            section.set_visible(true);
        }
        self.imp().updating_folder_rows.set(was_updating);
        tracing::info!(
            elapsed_ms = started.elapsed().as_millis() as u64,
            folder_count = folders.len(),
            roots_count,
            nodes_count,
            "EDS/Camel folder rows rebuilt"
        );
    }

    pub(crate) fn set_dynamic_folder_expanded(&self, folder_id: &str, expanded: bool) {
        let mut set = self.imp().dynamic_folder_expanded.borrow_mut();
        let changed = if expanded {
            set.insert(folder_id.to_string())
        } else {
            set.remove(folder_id)
        };
        if changed {
            let set_clone = set.clone();
            drop(set);
            self.persist_dynamic_folder_expanded(&set_clone);
        }
    }

    pub(crate) fn persist_dynamic_folder_expanded(&self, expanded: &HashSet<String>) {
        if let Some(settings) = AppSettings::try_new() {
            let mut list: Vec<String> = expanded.iter().cloned().collect();
            list.sort();
            settings.set_mail_expanded_folders(&list);
        }
    }

    pub(crate) fn canonical_account_uid(uid: &str) -> &str {
        uid.strip_prefix("eds:").unwrap_or(uid)
    }

    fn dynamic_folder_key(source_uid: &str, folder_name: &str) -> String {
        let canonical_src = Self::canonical_account_uid(source_uid);
        format!("{canonical_src}\u{0}{folder_name}")
    }

    fn parent_folder_name(folder_name: &str) -> Option<String> {
        folder_name
            .rsplit_once('/')
            .map(|(parent, _)| parent.to_string())
            .filter(|parent| !parent.is_empty())
    }

    fn folder_icon_name(folder_id: &str) -> &'static str {
        let clean = folder_id.trim().to_ascii_lowercase();
        if clean.contains("inbox") || clean.contains("posteingang") {
            "mail-inbox-symbolic"
        } else if clean.contains("sent")
            || clean.contains("gesendet")
            || clean.contains("gesendete")
        {
            "mail-send-symbolic"
        } else if clean.contains("draft") || clean.contains("entwurf") || clean.contains("entwürfe")
        {
            "mail-drafts-symbolic"
        } else if clean.contains("trash")
            || clean.contains("mülleimer")
            || clean.contains("papierkorb")
            || clean.contains("gelöschte")
            || clean.contains("deleted")
        {
            "user-trash-symbolic"
        } else if clean.contains("junk") || clean.contains("spam") {
            "mail-mark-junk-symbolic"
        } else if clean.contains("archive") || clean.contains("archiv") {
            "folder-symbolic"
        } else if clean.contains("outbox") || clean.contains("postausgang") {
            "mail-outbox-symbolic"
        } else {
            "folder-symbolic"
        }
    }

    fn local_folder_label(folder_id: &str) -> String {
        folder_id
            .strip_prefix("custom:")
            .unwrap_or(folder_id)
            .replace('/', " / ")
    }

    fn mail_message_location_label(&self, message: &MailMessageObject) -> String {
        let location = message.backend_location();
        let folder_id = message.folder_id();
        mail_message_location_label(
            &folder_id,
            location.as_ref(),
            &self.imp().mail_folder_summaries.borrow(),
        )
    }

    #[cfg(test)]
    fn is_builtin_folder_id(folder_id: &str) -> bool {
        matches!(
            folder_id,
            "all" | "inbox" | "sent" | "drafts" | "trash" | "archive" | "junk" | "spam"
        )
    }

    fn format_drawer_folder_status(
        selection: &FolderSelection,
        unread: u32,
        total: usize,
    ) -> String {
        if total == 0 {
            return String::new();
        }
        let fid = selection.folder_id.to_ascii_lowercase();
        let fname = selection
            .folder_name
            .as_deref()
            .unwrap_or("")
            .to_ascii_lowercase();

        if fid.contains("sent")
            || fid.contains("gesendet")
            || fname.contains("sent")
            || fname.contains("gesendet")
        {
            format!("{total} sent")
        } else if fid.contains("draft")
            || fid.contains("entwurf")
            || fname.contains("draft")
            || fname.contains("entwurf")
        {
            format!("{total} drafts")
        } else if fid.contains("trash")
            || fid.contains("papierkorb")
            || fid.contains("gelöschte")
            || fid.contains("geloeschte")
            || fid.contains("deleted")
            || fname.contains("trash")
            || fname.contains("papierkorb")
            || fname.contains("gelöschte")
            || fname.contains("geloeschte")
            || fname.contains("deleted")
        {
            format!("{total} deleted")
        } else if fid.contains("junk")
            || fid.contains("spam")
            || fname.contains("junk")
            || fname.contains("spam")
        {
            format!("{total} junk")
        } else if unread > 0 {
            format!("{unread} unread, {total} total")
        } else {
            format!("{total} total")
        }
    }

    pub(crate) fn format_drawer_folder_tooltip(
        selection: &FolderSelection,
        display_title: &str,
        unread: u32,
        total: usize,
    ) -> String {
        let raw_title = selection.folder_name.as_deref().unwrap_or("");
        let title_display = if !raw_title.is_empty() && raw_title != display_title {
            format!("{display_title} ({raw_title})")
        } else {
            display_title.to_string()
        };

        if total == 0 {
            return format!("{title_display} ({})", crate::i18n::gettext("No emails"));
        }

        let fid = selection.folder_id.to_ascii_lowercase();
        let fname = selection
            .folder_name
            .as_deref()
            .unwrap_or("")
            .to_ascii_lowercase();

        let is_sent = fid.contains("sent")
            || fid.contains("gesendet")
            || fname.contains("sent")
            || fname.contains("gesendet");
        let is_drafts = fid.contains("draft")
            || fid.contains("entwurf")
            || fname.contains("draft")
            || fname.contains("entwurf");
        let is_trash = fid.contains("trash")
            || fid.contains("papierkorb")
            || fid.contains("gelöschte")
            || fid.contains("geloeschte")
            || fid.contains("deleted")
            || fname.contains("trash")
            || fname.contains("papierkorb")
            || fname.contains("gelöschte")
            || fname.contains("geloeschte")
            || fname.contains("deleted");
        let is_junk = fid.contains("junk")
            || fid.contains("spam")
            || fname.contains("junk")
            || fname.contains("spam");

        if unread > 0 {
            let total_str = ngettext("1 total", "{} total", total as u32).replace("{}", &total.to_string());
            let unread_str = ngettext("1 unread", "{} unread", unread).replace("{}", &unread.to_string());
            format!("{title_display}: {unread_str}, {total_str}")
        } else if is_sent {
            let sent_str = ngettext("1 sent email", "{} sent emails", total as u32).replace("{}", &total.to_string());
            format!("{title_display}: {sent_str}")
        } else if is_drafts {
            let draft_str = ngettext("1 draft", "{} drafts", total as u32).replace("{}", &total.to_string());
            format!("{title_display}: {draft_str}")
        } else if is_trash {
            let trash_str = ngettext("1 deleted email", "{} deleted emails", total as u32).replace("{}", &total.to_string());
            format!("{title_display}: {trash_str}")
        } else if is_junk {
            let junk_str = ngettext("1 junk email", "{} junk emails", total as u32).replace("{}", &total.to_string());
            format!("{title_display}: {junk_str}")
        } else if total == 1 {
            format!("{title_display}: {}", gettext("1 email"))
        } else {
            let emails_str = ngettext("{} email", "{} emails", total as u32).replace("{}", &total.to_string());
            format!("{title_display}: {emails_str}")
        }
    }

    fn unread_message_count(&self) -> u32 {
        let Some(store) = self.imp().message_store.borrow().as_ref().cloned() else {
            return 0;
        };
        let mut count = 0u32;
        for i in 0..store.n_items() {
            if let Some(msg) = store.item(i).and_downcast::<MailMessageObject>() {
                if msg.is_unread() {
                    count += 1;
                }
            }
        }
        count
    }

    pub(crate) fn clean_folder_display_title(raw_title: &str) -> String {
        let stripped = raw_title
            .strip_prefix("[Gmail]/")
            .or_else(|| raw_title.strip_prefix("[Google Mail]/"))
            .unwrap_or(raw_title);
        let leaf = stripped.rsplit('/').next().unwrap_or(stripped);
        Self::localize_folder_name(leaf)
    }

    fn update_drawer_header_with_selection(
        &self,
        selection: &FolderSelection,
        total_override: Option<usize>,
    ) {
        let (raw_title, icon) = selection.title_and_icon();
        let display_title = Self::clean_folder_display_title(&raw_title);
        if let Some(win) = crate::window::find_evolution_window(self) {
            win.update_sidebar_title(&display_title);
        }
        if let Some(title_lbl) = self.imp().drawer_header_title.borrow().as_ref() {
            title_lbl.set_label(&display_title);
        }
        if let Some(icon_img) = self.imp().drawer_header_icon.borrow().as_ref() {
            icon_img.set_icon_name(Some(icon));
        }

        let total = total_override.unwrap_or_else(|| {
            self.imp()
                .message_store
                .borrow()
                .as_ref()
                .map(gtk::prelude::ListModelExt::n_items)
                .unwrap_or(0) as usize
        });
        let unread = self.unread_message_count();

        if let Some(total_lbl) = self.imp().drawer_header_total.borrow().as_ref() {
            if unread > 0 {
                total_lbl.set_label(&unread.to_string());
                total_lbl.set_visible(true);
            } else {
                total_lbl.set_label("");
                total_lbl.set_visible(false);
            }
        }

        let tooltip = Self::format_drawer_folder_tooltip(selection, &display_title, unread, total);
        if let Some(header_box) = self.imp().drawer_header_box.borrow().as_ref() {
            header_box.set_tooltip_text(Some(&tooltip));
        }
        if let Some(title_lbl) = self.imp().drawer_header_title.borrow().as_ref() {
            title_lbl.set_tooltip_text(Some(&tooltip));
        }
        if let Some(icon_img) = self.imp().drawer_header_icon.borrow().as_ref() {
            icon_img.set_tooltip_text(Some(&tooltip));
        }
        if let Some(total_lbl) = self.imp().drawer_header_total.borrow().as_ref() {
            total_lbl.set_tooltip_text(Some(&tooltip));
        }
    }

    pub(crate) fn update_drawer_header(&self) {
        let selection = self.active_folder_selection();
        self.update_drawer_header_with_selection(&selection, None);
    }

    fn select_folder_row(&self, selection: &FolderSelection) {
        if let Some(unified_list) = self.imp().unified_folder_list.borrow().as_ref() {
            if selection.folder_id.starts_with("unified_") {
                self.imp().updating_folder_rows.set(true);
                let mut matching_row = None;
                for index in 0..unified_list.observe_children().n_items() {
                    let Some(row) = unified_list
                        .row_at_index(index as i32)
                        .and_downcast::<gtk::ListBoxRow>()
                    else {
                        continue;
                    };
                    let row_id = unsafe {
                        row.data::<String>("folder-id")
                            .map(|p| p.as_ref().clone())
                    };
                    if row_id.as_deref() == Some(&selection.folder_id) {
                        matching_row = Some(row);
                        break;
                    }
                }
                unified_list.select_row(matching_row.as_ref());
                if let Some(folder_list) = self.imp().folder_list.borrow().as_ref() {
                    folder_list.unselect_all();
                }
                if let Some(dynamic_selection) = self.imp().dynamic_folder_selection.borrow().as_ref() {
                    dynamic_selection.set_selected(gtk::INVALID_LIST_POSITION);
                }
                if let Some(search_list) = self.imp().search_list.borrow().as_ref() {
                    search_list.unselect_all();
                }
                self.imp().updating_folder_rows.set(false);
                self.update_drawer_header_with_selection(selection, None);
                return;
            } else {
                unified_list.unselect_all();
            }
        }

        let Some(folder_list) = self.imp().folder_list.borrow().as_ref().cloned() else {
            return;
        };

        self.imp().updating_folder_rows.set(true);
        let mut matching_row = None;
        for index in 0..folder_list.observe_children().n_items() {
            let Some(row) = folder_list
                .row_at_index(index as i32)
                .and_downcast::<gtk::ListBoxRow>()
            else {
                continue;
            };
            if Self::folder_row_data(&row)
                .map(|data| data.selection() == *selection)
                .unwrap_or(false)
            {
                matching_row = Some(row);
                break;
            }
        }
        folder_list.select_row(matching_row.as_ref());
        if let Some(dynamic_selection) = self
            .imp()
            .dynamic_folder_selection
            .borrow()
            .as_ref()
            .cloned()
        {
            if matching_row.is_some() {
                dynamic_selection.set_selected(gtk::INVALID_LIST_POSITION);
            } else {
                if let Some(source_uid) = selection.source_uid.as_deref() {
                    let mut ancestors = vec![String::new()];
                    if let Some(folder_name) = selection.folder_name.as_deref() {
                        let mut path = String::new();
                        let mut components = folder_name.split('/').peekable();
                        while let Some(component) = components.next() {
                            if components.peek().is_none() {
                                break;
                            }
                            if !path.is_empty() {
                                path.push('/');
                            }
                            path.push_str(component);
                            ancestors.push(path.clone());
                        }
                    }
                    let mut newly_expanded = false;
                    for ancestor in ancestors {
                        for index in 0..dynamic_selection.n_items() {
                            let Some(row) = dynamic_selection
                                .item(index)
                                .and_downcast::<gtk::TreeListRow>()
                            else {
                                continue;
                            };
                            let Some(folder) = row.item().and_downcast::<FolderObject>() else {
                                continue;
                            };
                            let folder_name = folder.folder_name().unwrap_or_default();
                            let is_match = if ancestor.is_empty() {
                                row.depth() == 0
                                    && folder.source_uid().as_deref() == Some(source_uid)
                            } else {
                                folder.source_uid().as_deref() == Some(source_uid)
                                    && folder_name == ancestor
                            };
                            if is_match {
                                if !row.is_expanded() {
                                    row.set_expanded(true);
                                    self.imp()
                                        .dynamic_folder_expanded
                                        .borrow_mut()
                                        .insert(folder.id());
                                    newly_expanded = true;
                                }
                                break;
                            }
                        }
                    }
                    if newly_expanded {
                        let expanded_snapshot = self.imp().dynamic_folder_expanded.borrow().clone();
                        self.persist_dynamic_folder_expanded(&expanded_snapshot);
                    }
                }
                for index in 0..dynamic_selection.n_items() {
                    let Some(row) = dynamic_selection
                        .item(index)
                        .and_downcast::<gtk::TreeListRow>()
                    else {
                        continue;
                    };
                    if row.depth() == 0 && selection.folder_name.is_some() {
                        continue;
                    }
                    let Some(folder) = row.item().and_downcast::<FolderObject>() else {
                        continue;
                    };
                    let current = FolderSelection {
                        folder_id: folder.id(),
                        source_uid: folder.source_uid(),
                        folder_name: folder
                            .folder_name()
                            .filter(|folder_name| !folder_name.trim().is_empty()),
                    };
                    let is_match = if current == *selection {
                        true
                    } else if let (Some(sel_src), Some(cur_src)) = (
                        selection.source_uid.as_deref(),
                        current.source_uid.as_deref(),
                    ) {
                        sel_src == cur_src
                            && selection.folder_name.as_deref() == current.folder_name.as_deref()
                    } else {
                        folder.id() == selection.folder_id
                    };
                    if is_match {
                        dynamic_selection.set_selected(index);
                        break;
                    }
                }
            }
        }
        self.imp().updating_folder_rows.set(false);
        self.update_drawer_header_with_selection(selection, None);
    }

    fn build_unified_mail_toolbar(
        &self,
        columns_button: &gtk::MenuButton,
    ) -> gtk::Box {
        let toolbar = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .margin_start(6)
            .margin_end(6)
            .margin_top(2)
            .margin_bottom(2)
            .css_classes(vec!["unified-mail-toolbar", "toolbar"])
            .build();

        let make_button = |icon_name: &str, tooltip: &str, action_name: &str| {
            let button = gtk::Button::builder()
                .icon_name(icon_name)
                .tooltip_text(tooltip)
                .action_name(action_name)
                .css_classes(vec!["flat"])
                .valign(gtk::Align::Center)
                .build();
            let fallback = match icon_name {
                "mail-reply-sender-symbolic" | "mail-reply-all-symbolic" => "go-previous-symbolic",
                "mail-forward-symbolic" => "go-next-symbolic",
                "document-save-symbolic" => "document-save-symbolic",
                "document-print-symbolic" => "document-save-symbolic",
                "document-print-preview-symbolic" => "document-print-symbolic",
                "mail-read-symbolic" | "mail-unread-symbolic" => "mail-message-new-symbolic",
                "starred-symbolic" => "starred-symbolic",
                "mail-mark-important-symbolic" => "dialog-warning-symbolic",
                "mail-mark-junk-symbolic" => "dialog-warning-symbolic",
                "folder-symbolic" => "folder-symbolic",
                "edit-copy-symbolic" => "edit-copy-symbolic",
                _ => "image-missing-symbolic",
            };
            set_button_icon_with_fallback(&button, icon_name, fallback);
            set_accessible_label(&button, tooltip);
            button
        };

        // 0. Communication Group: Reply, Reply All, Forward (.linked)
        let str_reply = crate::i18n::gettext("Reply (Ctrl+R)");
        let str_reply_all = crate::i18n::gettext("Reply All (Ctrl+Shift+R)");
        let str_forward = crate::i18n::gettext("Forward (Ctrl+L)");
        let reply_btn = make_button("mail-reply-sender-symbolic", &str_reply, "win.reply");
        let reply_all_btn = make_button("mail-reply-all-symbolic", &str_reply_all, "win.reply-all");
        let forward_btn = make_button("mail-forward-symbolic", &str_forward, "win.forward");
        let comm_group = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["linked"])
            .valign(gtk::Align::Center)
            .build();
        comm_group.append(&reply_btn);
        comm_group.append(&reply_all_btn);
        comm_group.append(&forward_btn);

        // 1. Print Action
        let print_btn = make_button(
            "document-print-symbolic",
            &crate::i18n::gettext("Print message (Ctrl+P)"),
            "win.mail-print",
        );

        // 2. Triage & Organize Group: Delete, Archive, Junk, Move, Copy (.linked)
        let delete_btn = make_button(
            "user-trash-symbolic",
            &crate::i18n::gettext("Delete message (Del)"),
            "win.delete",
        );
        let archive_btn = make_button(
            "package-x-generic-symbolic",
            &crate::i18n::gettext("Archive message"),
            "win.archive",
        );
        set_button_icon_with_fallback(&archive_btn, "package-x-generic-symbolic", "folder-symbolic");

        let junk_btn = make_button(
            "mail-mark-junk-symbolic",
            &crate::i18n::gettext("Mark as junk (Ctrl+J)"),
            "win.mark-junk",
        );
        let _action_mark_not_junk = "win.mark-not-junk";

        let move_popover_content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(4)
            .margin_start(8)
            .margin_end(8)
            .margin_top(8)
            .margin_bottom(8)
            .build();
        let move_popover = gtk::Popover::builder().child(&move_popover_content).build();
        let page_for_single_move = self.downgrade();
        let move_popover_weak = move_popover.downgrade();
        move_popover.connect_show(move |_| {
            while let Some(child) = move_popover_content.first_child() {
                move_popover_content.remove(&child);
            }
            let Some(page) = page_for_single_move.upgrade() else {
                return;
            };
            let Some(message) = page.selected_message() else {
                move_popover_content.append(
                    &gtk::Label::builder()
                        .label(&gettext("No message selected"))
                        .css_classes(vec!["caption", "dim-label"])
                        .build(),
                );
                return;
            };
            let destinations =
                page.folder_destinations_for_messages(std::slice::from_ref(&message));
            if destinations.is_empty() {
                move_popover_content.append(
                    &gtk::Label::builder()
                        .label(&gettext("No target folders available"))
                        .css_classes(vec!["caption", "dim-label"])
                        .build(),
                );
                return;
            }
            for destination in destinations {
                let button = gtk::Button::builder()
                    .label(&destination.label)
                    .halign(gtk::Align::Fill)
                    .css_classes(vec!["flat"])
                    .build();
                let page_for_destination = page.downgrade();
                let popover_for_destination = move_popover_weak.clone();
                let destination_source = destination.source_uid.clone();
                let destination_folder = destination.folder_name.clone();
                button.connect_clicked(move |_| {
                    if let Some(page) = page_for_destination.upgrade() {
                        match page.move_selected_to(&destination_source, &destination_folder) {
                            Ok(true) => {}
                            Ok(false) => page.show_toast(&gettext("No message selected")),
                            Err(error) => {
                                page.show_toast(&format!("{}: {error}", gettext("Move not possible")))
                            }
                        }
                    }
                    if let Some(popover) = popover_for_destination.upgrade() {
                        popover.popdown();
                    }
                });
                move_popover_content.append(&button);
            }
        });
        let str_move_tip = crate::i18n::gettext("Move message");
        let move_button = gtk::MenuButton::builder()
            .icon_name("folder-symbolic")
            .tooltip_text(&str_move_tip)
            .popover(&move_popover)
            .css_classes(vec!["flat"])
            .valign(gtk::Align::Center)
            .build();
        set_accessible_label(&move_button, &str_move_tip);

        let copy_popover_content = gtk::Box::builder()
            .orientation(gtk::Orientation::Vertical)
            .spacing(4)
            .margin_start(8)
            .margin_end(8)
            .margin_top(8)
            .margin_bottom(8)
            .build();
        let copy_popover = gtk::Popover::builder().child(&copy_popover_content).build();
        let page_for_single_copy = self.downgrade();
        let copy_popover_weak = copy_popover.downgrade();
        copy_popover.connect_show(move |_| {
            while let Some(child) = copy_popover_content.first_child() {
                copy_popover_content.remove(&child);
            }
            let Some(page) = page_for_single_copy.upgrade() else {
                return;
            };
            let Some(message) = page.selected_message() else {
                copy_popover_content.append(
                    &gtk::Label::builder()
                        .label(&gettext("No message selected"))
                        .css_classes(vec!["caption", "dim-label"])
                        .build(),
                );
                return;
            };
            let destinations =
                page.copy_folder_destinations_for_messages(std::slice::from_ref(&message));
            if destinations.is_empty() {
                copy_popover_content.append(
                    &gtk::Label::builder()
                        .label(&gettext("No target folders available"))
                        .css_classes(vec!["caption", "dim-label"])
                        .build(),
                );
                return;
            }
            for destination in destinations {
                let button = gtk::Button::builder()
                    .label(&destination.label)
                    .halign(gtk::Align::Fill)
                    .css_classes(vec!["flat"])
                    .build();
                let page_for_destination = page.downgrade();
                let popover_for_destination = copy_popover_weak.clone();
                let destination_source = destination.source_uid.clone();
                let destination_folder = destination.folder_name.clone();
                button.connect_clicked(move |_| {
                    if let Some(page) = page_for_destination.upgrade() {
                        match page.copy_selected_to(&destination_source, &destination_folder) {
                            Ok(true) => {}
                            Ok(false) => page.show_toast(&gettext("No message selected")),
                            Err(error) => {
                                page.show_toast(&format!("{}: {error}", gettext("Copy not possible")))
                            }
                        }
                    }
                    if let Some(popover) = popover_for_destination.upgrade() {
                        popover.popdown();
                    }
                });
                copy_popover_content.append(&button);
            }
        });
        let str_copy_tip = crate::i18n::gettext("Copy message");
        let copy_button = gtk::MenuButton::builder()
            .icon_name("edit-copy-symbolic")
            .tooltip_text(&str_copy_tip)
            .popover(&copy_popover)
            .css_classes(vec!["flat"])
            .valign(gtk::Align::Center)
            .build();
        set_accessible_label(&copy_button, &str_copy_tip);

        let triage_group = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["linked"])
            .valign(gtk::Align::Center)
            .build();
        triage_group.append(&delete_btn);
        triage_group.append(&archive_btn);
        triage_group.append(&junk_btn);
        triage_group.append(&move_button);
        triage_group.append(&copy_button);

        // 3. Spam & Status Group: Junk, Mark Read / Unread, Star, Important (.linked)
        let mark_read_btn = make_button(
            "mail-read-symbolic",
            &crate::i18n::gettext("Mark as read"),
            "win.mark-read",
        );
        let mark_unread_btn = make_button(
            "mail-unread-symbolic",
            &crate::i18n::gettext("Mark as unread"),
            "win.mark-unread",
        );
        let flag_btn = make_button(
            "starred-symbolic",
            &crate::i18n::gettext("Mark with star"),
            "win.toggle-flag",
        );
        let important_btn = make_button(
            "mail-mark-important-symbolic",
            &crate::i18n::gettext("Mark as important"),
            "win.toggle-important",
        );

        self.imp()
            .mark_read_button
            .replace(Some(mark_read_btn.clone()));
        self.imp()
            .mark_unread_button
            .replace(Some(mark_unread_btn.clone()));

        let show_status_actions = AppSettings::try_new()
            .map(|settings| settings.mail_show_mark_read_actions())
            .unwrap_or(true);

        let status_group = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["linked"])
            .valign(gtk::Align::Center)
            .visible(show_status_actions)
            .build();
        status_group.append(&mark_read_btn);
        status_group.append(&mark_unread_btn);
        status_group.append(&flag_btn);
        status_group.append(&important_btn);
        self.imp()
            .mail_status_group
            .replace(Some(status_group.clone()));

        let status_separator = gtk::Separator::builder()
            .orientation(gtk::Orientation::Vertical)
            .visible(show_status_actions)
            .build();
        self.imp()
            .mail_status_separator
            .replace(Some(status_separator.clone()));

        // 4. Navigation & History Group: Prev, Next (.linked) and Undo
        let str_prev = gettext("Previous message (k)");
        let prev_btn = make_button(
            "go-previous-symbolic",
            &str_prev,
            "win.mail-prev",
        );
        let str_next = gettext("Next message (j)");
        let next_btn = make_button(
            "go-next-symbolic",
            &str_next,
            "win.mail-next",
        );
        let nav_group = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .css_classes(vec!["linked"])
            .valign(gtk::Align::Center)
            .build();
        nav_group.append(&prev_btn);
        nav_group.append(&next_btn);

        let undo_btn = make_button(
            "edit-undo-symbolic",
            &crate::i18n::gettext("Undo last action"),
            "win.undo",
        );

        // 5. View Configuration: Columns Button
        columns_button.set_valign(gtk::Align::Center);

        let sidebar_visible = AppSettings::try_new()
            .map(|settings| settings.mail_show_sidebar())
            .unwrap_or(true);
        let str_sidebar_tip = gettext("Toggle sidebar (F9)");
        let str_sidebar_acc = gettext("Show or hide sidebar");
        let sidebar_toggle = gtk::ToggleButton::builder()
            .icon_name("sidebar-show-symbolic")
            .tooltip_text(&str_sidebar_tip)
            .active(sidebar_visible)
            .css_classes(vec!["flat"])
            .valign(gtk::Align::Center)
            .build();
        set_accessible_label(&sidebar_toggle, &str_sidebar_acc);
        self.imp().mail_sidebar_toggle.replace(Some(sidebar_toggle.clone()));

        let page_weak_for_sidebar = self.downgrade();
        sidebar_toggle.connect_toggled(move |btn| {
            if let Some(page) = page_weak_for_sidebar.upgrade() {
                let is_active = btn.is_active();
                if let Some(win) = crate::window::find_evolution_window(&page) {
                    if win.is_sidebar_visible_for_active_view() != is_active {
                        win.toggle_sidebar_animated(is_active);
                        return;
                    }
                }
                page.set_sidebar_visible(is_active);
                if let Some(settings) = AppSettings::try_new() {
                    settings.set_mail_show_sidebar(is_active);
                }
            }
        });

        if let Some(settings) = AppSettings::try_new() {
            let sidebar_toggle_for_settings = sidebar_toggle.clone();
            settings.connect_changed(Some("mail-show-sidebar"), move |settings, _| {
                let active = settings.boolean("mail-show-sidebar");
                if sidebar_toggle_for_settings.is_active() != active {
                    sidebar_toggle_for_settings.set_active(active);
                }
            });
        }

        let todo_visible = AppSettings::try_new()
            .map(|settings| settings.mail_show_todo_bar())
            .unwrap_or(false);
        let str_todo_tip = gettext("Toggle To Do bar");
        let str_todo_acc = gettext("Show or hide To Do bar");
        let preview_toggle = gtk::ToggleButton::builder()
            .icon_name("sidebar-show-right-symbolic")
            .tooltip_text(&str_todo_tip)
            .active(todo_visible)
            .css_classes(vec!["flat"])
            .valign(gtk::Align::Center)
            .build();
        set_accessible_label(&preview_toggle, &str_todo_acc);
        self.imp().mail_preview_toggle.replace(Some(preview_toggle.clone()));
        self.imp().mail_todo_toggle.replace(Some(preview_toggle.clone()));

        let page_weak_for_todo = self.downgrade();
        preview_toggle.connect_toggled(move |btn| {
            if let Some(page) = page_weak_for_todo.upgrade() {
                let is_active = btn.is_active();
                page.set_todo_bar_visible(is_active);
                if let Some(settings) = AppSettings::try_new() {
                    settings.set_mail_show_todo_bar(is_active);
                }
            }
        });

        if let Some(settings) = AppSettings::try_new() {
            let todo_toggle_for_settings = preview_toggle.clone();
            settings.connect_changed(Some("mail-show-todo-bar"), move |settings, _| {
                let active = settings.boolean("mail-show-todo-bar");
                if todo_toggle_for_settings.is_active() != active {
                    todo_toggle_for_settings.set_active(active);
                }
            });

            let status_group_for_settings = status_group.clone();
            let status_separator_for_settings = status_separator.clone();
            settings.connect_changed(Some("mail-show-mark-read-actions"), move |settings, _| {
                let active = settings.boolean("mail-show-mark-read-actions");
                status_group_for_settings.set_visible(active);
                status_separator_for_settings.set_visible(active);
            });
        }

        // Actions box containing all left action buttons
        let actions_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .build();

        actions_box.append(&comm_group);
        actions_box.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        actions_box.append(&triage_group);
        actions_box.append(&status_separator);
        actions_box.append(&status_group);
        actions_box.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        actions_box.append(&nav_group);
        actions_box.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        actions_box.append(&undo_btn);
        actions_box.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        let str_source_tip = crate::i18n::gettext("View message source (Ctrl+U)");
        let source_btn = make_button(
            "code-symbolic",
            &str_source_tip,
            "win.view-message-source",
        );
        set_button_icon_with_fallback(&source_btn, "code-symbolic", "document-properties-symbolic");

        actions_box.append(&print_btn);
        actions_box.append(&gtk::Separator::new(gtk::Orientation::Vertical));
        actions_box.append(&source_btn);

        let actions_scroll = gtk::ScrolledWindow::builder()
            .hscrollbar_policy(gtk::PolicyType::Automatic)
            .vscrollbar_policy(gtk::PolicyType::Never)
            .child(&actions_box)
            .propagate_natural_width(false)
            .min_content_width(0)
            .hexpand(true)
            .build();

        let pinned_right_box = gtk::Box::builder()
            .orientation(gtk::Orientation::Horizontal)
            .spacing(4)
            .valign(gtk::Align::Center)
            .halign(gtk::Align::End)
            .build();
        pinned_right_box.append(columns_button);

        toolbar.append(&actions_scroll);
        toolbar.append(&pinned_right_box);

        self.imp().mail_reply_button.replace(Some(reply_btn.clone()));
        self.imp().mail_reply_all_button.replace(Some(reply_all_btn.clone()));
        self.imp().mail_forward_button.replace(Some(forward_btn.clone()));
        self.imp().mail_print_button.replace(Some(print_btn.clone()));
        self.imp().mail_source_button.replace(Some(source_btn.clone()));
        self.imp().mail_delete_button.replace(Some(delete_btn.clone()));
        self.imp().mail_archive_button.replace(Some(archive_btn.clone()));
        self.imp().mail_move_button.replace(Some(move_button.clone()));
        self.imp().mail_copy_button.replace(Some(copy_button.clone()));
        self.imp().mail_junk_button.replace(Some(junk_btn.clone()));
        self.imp().mail_flag_button.replace(Some(flag_btn.clone()));
        self.imp().mail_important_button.replace(Some(important_btn.clone()));
        self.imp().mail_undo_button.replace(Some(undo_btn.clone()));

        toolbar
    }

    fn message_context_menu() -> gio::Menu {
        thread_local! {
            static CACHED_MESSAGE_CONTEXT_MENU: RefCell<Option<gio::Menu>> = const { RefCell::new(None) };
        }
        CACHED_MESSAGE_CONTEXT_MENU.with(|cached| {
            if let Some(ref menu) = *cached.borrow() {
                return menu.clone();
            }
            let menu = gio::Menu::new();

            // Section 1: Primary Respond Actions
            let respond_section = gio::Menu::new();
            respond_section.append(Some(&gettext("Reply")), Some("win.reply"));
            respond_section.append(Some(&gettext("Reply to All")), Some("win.reply-all"));
            respond_section.append(Some(&gettext("Forward")), Some("win.forward"));

            let forward_submenu = gio::Menu::new();
            forward_submenu.append(Some(&gettext("Forward Inline")), Some("win.forward-inline"));
            forward_submenu.append(Some(&gettext("Forward Quoted")), Some("win.forward-quoted"));
            forward_submenu.append(Some(&gettext("Forward as Attachment")), Some("win.forward-attached"));
            forward_submenu.append(Some(&gettext("Reply to List")), Some("win.reply-list"));
            forward_submenu.append(Some(&gettext("Reply Alternative…")), Some("win.reply-alternative"));
            respond_section.append_submenu(Some(&gettext("Forward As…")), &forward_submenu);
            menu.append_section(None, &respond_section);

            // Section 2: Organize / Triage
            let triage_section = gio::Menu::new();
            triage_section.append(Some(&gettext("Mark as Read")), Some("win.mark-read"));
            triage_section.append(Some(&gettext("Mark as Unread")), Some("win.mark-unread"));
            triage_section.append(Some(&gettext("Toggle Flag")), Some("win.toggle-flag"));
            triage_section.append(Some(&gettext("Archive")), Some("win.archive"));
            triage_section.append(Some(&gettext("Move to Folder…")), Some("win.move-message"));
            triage_section.append(Some(&gettext("Delete")), Some("win.delete"));
            menu.append_section(None, &triage_section);

            // Section 3: More Actions (Progressive Disclosure)
            let more_section = gio::Menu::new();
            let more_submenu = gio::Menu::new();

            let labels_junk_section = gio::Menu::new();
            labels_junk_section.append(Some(&gettext("Toggle Important")), Some("win.toggle-important"));
            labels_junk_section.append(Some(&gettext("Edit Labels…")), Some("win.edit-labels"));
            labels_junk_section.append(Some(&gettext("Copy to Folder…")), Some("win.copy-message"));
            labels_junk_section.append(Some(&gettext("Mark as Junk")), Some("win.mark-junk"));
            labels_junk_section.append(Some(&gettext("Mark as Not Junk")), Some("win.mark-not-junk"));
            labels_junk_section.append(Some(&gettext("Undelete")), Some("win.undelete"));
            more_submenu.append_section(None, &labels_junk_section);

            let tools_section = gio::Menu::new();
            tools_section.append(Some(&gettext("Add Sender to Address Book")), Some("win.add-sender-contact"));
            tools_section.append(Some(&gettext("Edit as New Message")), Some("win.edit-as-new"));
            tools_section.append(Some(&gettext("View Message Source")), Some("win.view-message-source"));
            tools_section.append(Some(&gettext("Save as EML…")), Some("win.export"));
            tools_section.append(Some(&gettext("Copy Message Link")), Some("win.copy-message-link"));
            tools_section.append(Some(&gettext("Go to Containing Folder")), Some("win.goto-containing-folder"));
            tools_section.append(Some(&gettext("Print…")), Some("win.mail-print"));
            tools_section.append(Some(&gettext("Print Preview…")), Some("win.mail-print-preview"));
            more_submenu.append_section(None, &tools_section);

            more_section.append_submenu(Some(&gettext("More Actions…")), &more_submenu);
            menu.append_section(None, &more_section);

            *cached.borrow_mut() = Some(menu.clone());
            menu
        })
    }

