    #[test]
    fn named_mail_profiles_match_upstream_visibility_and_custom_keeps_its_family() {
        for column in crate::services::settings_service::MAIL_LIST_COLUMN_IDS {
            assert_eq!(
                mail_list_profile_allows_column("messages", false, column),
                matches!(
                    column,
                    "avatar" | "status" | "attachment" | "flagged" | "follow-up" | "sender" | "subject" | "date"
                )
            );
            assert_eq!(
                mail_list_profile_allows_column("wide", true, column),
                matches!(column, "status" | "flagged" | "follow-up" | "messages")
            );
            assert_eq!(
                mail_list_profile_allows_column("cards", false, column),
                matches!(column, "avatar" | "status" | "flagged" | "follow-up" | "labels" | "preview")
            );
        }

        let messages_order =
            crate::services::settings_service::mail_list_profile_column_order("messages");
        let wide_order = crate::services::settings_service::mail_list_profile_column_order("wide");
        assert!(!mail_list_uses_wide_messages("custom", &messages_order));
        assert!(mail_list_uses_wide_messages("custom", &wide_order));
    }

    #[test]
    fn mail_labels_display_formatting_matches_configured_and_fallback() {
        use crate::services::settings_service::MailLabelDefinition;

        let defs = vec![
            MailLabelDefinition::new("_Wichtig", "#EF2929", Some("$Labelimportant".to_string())),
            MailLabelDefinition::new("_Dienstlich", "#F57900", Some("$Labelwork".to_string())),
            MailLabelDefinition::new("Projekt _X", "#729FCF", Some("$Labelprojekt_x".to_string())),
        ];

        // Known tags should format as display names without mnemonics
        let labels = vec!["$Labelimportant".to_string(), "$Labelwork".to_string()];
        assert_eq!(
            format_labels_for_display_with_defs(&labels, &defs),
            "Wichtig, Dienstlich"
        );

        // Case insensitivity
        let labels_ci = vec!["$labelIMPORTANT".to_string(), "$LabelWork".to_string()];
        assert_eq!(
            format_labels_for_display_with_defs(&labels_ci, &defs),
            "Wichtig, Dienstlich"
        );

        // Custom configured tag
        let custom_labels = vec!["$Labelprojekt_x".to_string()];
        assert_eq!(
            format_labels_for_display_with_defs(&custom_labels, &defs),
            "Projekt X"
        );

        // Fallback for unconfigured tags
        let unconfigured = vec!["$LabelUrgent_Task".to_string(), "invoice_2026".to_string()];
        assert_eq!(
            format_labels_for_display_with_defs(&unconfigured, &defs),
            "Urgent Task, invoice 2026"
        );

        // Empty case
        assert_eq!(format_labels_for_display_with_defs(&[], &defs), "");
    }

    #[test]
    fn test_folder_selection_title_and_icon() {
        let inbox = FolderSelection::from_folder_id("inbox");
        let (inbox_title, inbox_icon) = inbox.title_and_icon();
        assert_eq!(inbox_title, crate::i18n::gettext("Inbox"));
        assert_eq!(inbox_icon, "mail-inbox-symbolic");

        let sent = FolderSelection::from_folder_id("sent");
        let (sent_title, sent_icon) = sent.title_and_icon();
        assert_eq!(sent_title, crate::i18n::gettext("Sent"));
        assert_eq!(sent_icon, "mail-send-symbolic");

        let drafts = FolderSelection::from_folder_id("drafts");
        let (drafts_title, drafts_icon) = drafts.title_and_icon();
        assert_eq!(drafts_title, crate::i18n::gettext("Drafts"));
        assert_eq!(drafts_icon, "mail-drafts-symbolic");

        let trash = FolderSelection::from_folder_id("trash");
        let (trash_title, trash_icon) = trash.title_and_icon();
        assert_eq!(trash_title, crate::i18n::gettext("Trash"));
        assert_eq!(trash_icon, "user-trash-symbolic");

        let archive = FolderSelection::from_folder_id("archive");
        let (archive_title, archive_icon) = archive.title_and_icon();
        assert_eq!(archive_title, crate::i18n::gettext("Archive"));
        assert_eq!(archive_icon, "folder-symbolic");

        let spam = FolderSelection::from_folder_id("spam");
        let (spam_title, spam_icon) = spam.title_and_icon();
        assert_eq!(spam_title, crate::i18n::gettext("Junk"));
        assert_eq!(spam_icon, "mail-mark-junk-symbolic");

        let outbox = FolderSelection::from_folder_id("outbox");
        let (outbox_title, outbox_icon) = outbox.title_and_icon();
        assert_eq!(outbox_title, crate::i18n::gettext("Outbox"));
        assert_eq!(outbox_icon, "mail-outbox-symbolic");

        let custom_inbox = FolderSelection {
            folder_id: "remote-inbox".to_string(),
            source_uid: Some("account-1".to_string()),
            folder_name: Some("INBOX".to_string()),
        };
        assert_eq!(
            custom_inbox.title_and_icon(),
            ("INBOX".to_string(), "mail-inbox-symbolic")
        );
    }

